# ---- formatting ---------------------------------------------------------------------------

def sg(v: float, nd: int = 4) -> str:
    """Signed fixed-point with a true minus sign."""
    return f"{v:+.{nd}f}".replace("-", "−")


def us(v: float, nd: int = 4) -> str:
    return f"{v:.{nd}f}".replace("-", "−")


def ci(lo: float, hi: float, nd: int = 4) -> str:
    return f"[{sg(lo, nd)}, {sg(hi, nd)}]"


def n_(v) -> str:
    return f"{int(v):,}"


def long_date(iso: str) -> str:
    y, m, d = (int(p) for p in iso[:10].split("-"))
    return f"{d} {MONTHS[m - 1]} {y}"


def rk(rho: str) -> str:
    """Variable-key form of a rho label: 0.6 -> r06, prior -> prior."""
    return "prior" if rho == "prior" else "r" + rho.replace(".", "")


def wk(w: str) -> str:
    return "full" if w == "full" else f"w{w}"


def wlabel(w: str) -> str:
    return "full" if w == "full" else f"W = {w}"


def bench_for(w: str) -> str:
    return "bayes" if w == "full" else "window_bayes"


def sha256(path: Path) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for block in iter(lambda: f.read(1 << 20), b""):
            h.update(block)
    return h.hexdigest()


def git(*args: str) -> str:
    try:
        return subprocess.run(["git", "-C", str(ROOT), *args], capture_output=True, text=True,
                              check=True).stdout.strip()
    except Exception:
        return ""


_NUM = re.compile(r"^(\[?[+−-]?\d[\d,]*(\.\d+)?(e[+−-]?\d+)?%?(, [+−-]?\d[\d.]*\])?|—|n/a)$")


def table(headers: list[str], rows: list[list[str]], widths: list[int] | None = None) -> str:
    """A pipe table. `widths` sets the dash counts, which pandoc reads as relative column widths
    whenever a row is longer than 72 characters. Columns whose every cell is a number (or an
    interval) are right-aligned; with fixed decimals and explicit signs that aligns the decimals."""
    rows = [[str(c) for c in r] for r in rows]
    widths = widths or [max(3, len(h), *(len(r[i]) for r in rows)) for i, h in enumerate(headers)]
    numeric = [bool(rows) and all(_NUM.match(r[i]) for r in rows) for i in range(len(headers))]
    seps = ["-" * (max(3, w) - 1) + (":" if num else "-") for w, num in zip(widths, numeric)]
    out = ["| " + " | ".join(headers) + " |", "|" + "|".join(seps) + "|"]
    out += ["| " + " | ".join(r) + " |" for r in rows]
    return "\n".join(out)


def escape_md(text: str) -> str:
    """Make a verbatim markdown source safe for pandoc: outside code spans and fenced blocks,
    escape the characters pandoc would read as subscript (~), superscript (^) or math ($)."""
    out, fenced = [], False
    for line in text.split("\n"):
        if line.lstrip().startswith("```"):
            fenced = not fenced
            out.append(line)
            continue
        if fenced:
            out.append(line)
            continue
        parts = line.split("`")
        for i in range(0, len(parts), 2):
            parts[i] = re.sub(r"([~^$])", r"\\\1", parts[i])
        # pandoc needs a blank line before a list that follows a paragraph
        if re.match(r"^\s*([-*]|\d+\.)\s", line) and out and out[-1].strip():
            out.append("")
        out.append("`".join(parts))
    return "\n".join(out)


def demote(text: str, by: int = 1) -> str:
    """Push markdown headings down `by` levels and keep them unnumbered and out of the TOC."""
    out, fenced = [], False
    for line in text.split("\n"):
        if line.lstrip().startswith("```"):
            fenced = not fenced
        m = re.match(r"^(#+) (.*)$", line)
        if m and not fenced:
            out.append("#" * (len(m.group(1)) + by) + " " + m.group(2) + " {.unnumbered .unlisted}")
        else:
            out.append(line)
    return "\n".join(out)


def verbatim(text: str, by: int = 1) -> str:
    return demote(escape_md(text.strip("\n")), by)


# ---- the variable registry ----------------------------------------------------------------

class Vars:
    def __init__(self):
        self.tree: dict = {}
        self.rows: list[tuple[str, str, str, str]] = []

    def set(self, key: str, value, source: str, locator: str = "", fmt: str = "text") -> str:
        value = str(value)
        node = self.tree
        parts = key.split(".")
        for p in parts[:-1]:
            node = node.setdefault(p, {})
            if not isinstance(node, dict):
                raise KeyError(f"{key}: {p} is already a leaf")
        if parts[-1] in node:
            raise KeyError(f"duplicate variable {key}")
        node[parts[-1]] = value
        self.rows.append((key, source, locator, fmt))
        return value

    def get(self, key: str) -> str:
        node = self.tree
        for p in key.split("."):
            node = node[p]
        return node


def grab(text: str, pattern: str, what: str, flat: bool = True) -> str:
    """First group of `pattern` in `text` (whitespace collapsed unless flat=False); fails loudly."""
    if flat:
        text = re.sub(r"\s+", " ", text)
    m = re.search(pattern, text, flags=re.S)
    if not m:
        raise ValueError(f"paper_build: could not find {what} ({pattern!r})")
    return m.group(1)


# ---- inputs -------------------------------------------------------------------------------

class Inputs:
    def __init__(self, root: Path = ROOT):
        self.root = root
        s = pd.read_csv(root / "results" / "summary.csv", dtype={"rho": str, "window": str})
        s["rho"] = s["rho"].map(lambda r: "prior" if r == "prior" else f"{float(r):.1f}")
        s["values"] = s["values"].map(json.loads)
        self.S = s
        self.idx = {(r.family, r.size, r.window, int(r.step), r.rho, int(r.h), r.bench, r.column): r
                    for r in s.itertuples()}
        self.H = json.loads((root / "results" / "hypotheses.json").read_text())
        self.cfg = json.loads((root / "configs" / "grid.json").read_text())
        self.prereg = (root / "docs" / "PREREG.md").read_text()
        self.decisions = (root / "docs" / "DECISIONS.md").read_text()
        self.gate = json.loads((root / "results" / "gate.json").read_text())
        self._metrics = None

    def row(self, size, window, rho, column, *, step=30000, h=1, bench=None, family="A"):
        bench = bench or bench_for(window)
        return self.idx[(family, size, str(window), step, rho, h, bench, column)]

    @property
    def metrics(self) -> pd.DataFrame:
        if self._metrics is None:
            frames = [pd.read_csv(p, dtype={"rho": str, "window": str})
                      for p in sorted((self.root / "results" / "metrics").glob("*.csv"))]
            m = pd.concat(frames, ignore_index=True)
            m["rho"] = m["rho"].map(lambda r: "prior" if r == "prior" else f"{float(r):.1f}")
            self._metrics = m
        return self._metrics

    def prereg_sections(self) -> dict[str, str]:
        return _split_sections(self.prereg)

    def decision_entries(self) -> list[tuple[str, str]]:
        parts = re.split(r"(?m)^## ", self.decisions)
        return [(p.split("\n", 1)[0].strip(), "## " + p.rstrip() + "\n") for p in parts[1:]]


def _split_sections(text: str) -> dict[str, str]:
    parts = re.split(r"(?m)^## ", text)
    out = {"_preamble": parts[0]}
    for p in parts[1:]:
        out[p.split("\n", 1)[0].strip()] = "## " + p.rstrip() + "\n"
    return out


def t_interval(values) -> tuple[float, float, float, float]:
    v = np.asarray(values, dtype=float)
    n = v.size
    half = float(stats.t.ppf(0.975, n - 1)) * v.std(ddof=1) / math.sqrt(n)
    return float(v.mean()), float(v.std(ddof=1)), float(v.mean() - half), float(v.mean() + half)


def widest_end(rows) -> tuple[float, str]:
    """The interval end furthest from zero among `rows`, with the rho where it sits."""
    best, where = 0.0, ""
    for r in rows:
        for e in (r.lo, r.hi):
            if abs(e) > abs(best):
                best, where = float(e), r.rho
    return best, where


# ---- variables ----------------------------------------------------------------------------

def tags(inp: Inputs) -> list[dict]:
    """The pre-registration tags from git: name, tag object, commit, tagger date (UTC), subject."""
    out = []
    raw = git("for-each-ref", "--sort=taggerdate",
              "--format=%(refname:short)|%(objectname)|%(*objectname)|%(taggerdate:iso-strict)|%(subject)",
              "refs/tags/prereg-*")
    for line in raw.splitlines():
        name, obj, commit, date, subject = line.split("|", 4)
        utc = datetime.fromisoformat(date).astimezone(timezone.utc)
        out.append({"name": name, "tag_object": obj, "commit": commit,
                    "utc": utc.strftime("%Y-%m-%d %H:%M"), "subject": subject})
    return out


def ledgers(root: Path = ROOT) -> pd.DataFrame:
    frames = []
    files = [root / "results" / "ledger.csv"] + sorted((root / "results" / "cloud").glob("ledger*.csv"))
    for p in files:
        f = pd.read_csv(p)
        f["ledger"] = p.relative_to(root).as_posix()
        frames.append(f)
    return pd.concat(frames, ignore_index=True)


def eor_table(inp: Inputs) -> pd.DataFrame:
    """Seed-level error-on-revision at size l, step 30,000, against the matching benchmark."""
    m = inp.metrics
    m = m[(m.family == "A") & (m["size"] == "l") & (m.step == 30000) & (m.h <= 5)]
    rows = []
    for w in WINDOWS:
        g = m[(m.window == w) & (m.bench == bench_for(w))]
        for h in range(1, 6):
            for rho in RHO_KEYS:
                gg = g[(g.h == h) & (g.rho == rho)].sort_values("seed")
                d = (gg.eor_b - gg.bench_eor_b).to_numpy()
                mean, sd, lo, hi = t_interval(d)
                rows.append({"window": w, "h": h, "rho": rho, "n": len(d),
                             "model_b": float(gg.eor_b.mean()), "bench_b": float(gg.bench_eor_b.mean()),
                             "diff": mean, "sd": sd, "lo": lo, "hi": hi, "values": list(d)})
    return pd.DataFrame(rows)


def kappa_table(inp: Inputs) -> pd.DataFrame:
    m = inp.metrics
    m = m[(m.family == "A") & (m["size"] == "l") & (m.step == 30000) & (m.h == 1) & (m.bench == "bayes")]
    rows = []
    for w in WINDOWS:
        for rho in RHO_KEYS:
            gg = m[(m.window == w) & (m.rho == rho)].sort_values("seed")
            mean, sd, lo, hi = t_interval(gg.kappa.to_numpy())
            rows.append({"window": w, "rho": rho, "n": len(gg), "mean": mean, "sd": sd, "lo": lo,
                         "hi": hi, "values": list(gg.kappa)})
    return pd.DataFrame(rows)


def counts(inp: Inputs, size: str, window: str, step: int = 30000, hs=(1,), family="A") -> dict:
    c = {"equivalent": 0, "different": 0, "inconclusive": 0}
    for h in hs:
        for rho in RHOS:
            for col in COLS:
                c[inp.row(size, window, rho, col, step=step, h=h, family=family).verdict] += 1
    return c


def build_variables(inp: Inputs) -> Vars:
    V = Vars()
    H, cfg = inp.H, inp.cfg
    SUM, HYP, CFG = "results/summary.csv", "results/hypotheses.json", "configs/grid.json"
    PRE, DEC = "docs/PREREG.md", "docs/DECISIONS.md"

    # -- meta
    V.set("meta.date", long_date(PAPER_DATE), "analysis/paper_build.py", "PAPER_DATE", "date")
    V.set("meta.repo_url", REPO_URL, DEC, "entry: repository made public")
    V.set("meta.repo_short", REPO_URL.replace("https://", ""), DEC, "entry: repository made public")
    V.set("meta.doi", DOI, "analysis/paper_build.py", "Zenodo concept DOI (all versions)")
    V.set("meta.licence.code", "MIT licence", "LICENSE", "title")
    V.set("meta.licence.text", "CC BY 4.0", "analysis/paper_build.py", "licence of text, results and figures")
    public = grab(inp.decisions, r"## (2026-\d\d-\d\d): repository made public", "public date")
    V.set("meta.public_date", long_date(public), DEC, "entry: repository made public", "date")
    V.set("meta.public_time", grab(inp.decisions, r"\(public\) at (\d\d:\d\d) UTC", "public time"),
          DEC, "entry: repository made public")

    # -- design constants
    sizes = cfg["sizes"]
    try:
        from rt.sweep import grid as _grid
        from rt.train import build_model
        cells = _grid(cfg)
        n_planned = len(cells)
        n_fam = {f: sum(c.family == f for c in cells) for f in "AB"}
        params = {s: sum(p.numel() for p in build_model(cfg, s).parameters()) for s in SIZES}
    except Exception:                                   # torch missing: fall back to the config
        n_planned = len(SIZES) * 5 * 5 + 25
        n_fam = {"A": 100, "B": 25}
        params = {s: float("nan") for s in SIZES}
    for s in SIZES:
        V.set(f"design.size.{s}.layers", sizes[s][0], CFG, f"sizes.{s}[0]", "int")
        V.set(f"design.size.{s}.d", sizes[s][1], CFG, f"sizes.{s}[1]", "int")
        V.set(f"design.size.{s}.heads", sizes[s][2], CFG, f"sizes.{s}[2]", "int")
        V.set(f"design.size.{s}.params", n_(params[s]) if params[s] == params[s] else "n/a",
              "rt/model.py", f"parameter count of build_model(cfg, {s})", "int")
    V.set("design.n_sizes", len(sizes), CFG, "len(sizes)", "int")
    V.set("design.n_windows", len(cfg["windows"]), CFG, "len(windows)", "int")
    V.set("design.windows_finite", ", ".join(str(w) for w in cfg["windows"] if w), CFG, "windows")
    V.set("design.n_seeds", len(cfg["seeds"]), CFG, "len(seeds)", "int")
    V.set("design.seeds", ", ".join(str(s) for s in cfg["seeds"]), CFG, "seeds")
    V.set("design.t_max", cfg["t_max"], CFG, "t_max", "int")
    V.set("design.t_sim", cfg["t_max"] + cfg["horizons"], CFG, "t_max + horizons", "int")
    V.set("design.horizons", cfg["horizons"], CFG, "horizons", "int")
    V.set("design.eval_t_first", 41, "rt/sim.py", "T_EVAL", "int")
    V.set("design.eval_t_last", 80, "rt/sim.py", "T_EVAL", "int")
    V.set("design.eval_n_origins", 40, "rt/sim.py", "len(T_EVAL)", "int")
    V.set("design.lr", cfg["lr"], CFG, "lr")
    V.set("design.weight_decay", cfg["weight_decay"], CFG, "weight_decay")
    V.set("design.beta1", cfg["betas"][0], CFG, "betas[0]")
    V.set("design.beta2", cfg["betas"][1], CFG, "betas[1]")
    V.set("design.warmup", n_(cfg["warmup_steps"]), CFG, "warmup_steps", "int")
    V.set("design.steps", n_(cfg["max_steps"]), CFG, "max_steps", "int")
    V.set("design.steps_long", n_(2 * cfg["max_steps"]), PRE, "section 6: 60,000", "int")
    V.set("design.batch", n_(cfg["batch_size"]), CFG, "batch_size", "int")
    ck = [n_(c) for c in cfg["checkpoints"]]
    V.set("design.checkpoints", ", ".join(ck[:-1]) + " and " + ck[-1], CFG, "checkpoints")
    V.set("design.n_checkpoints", len(ck), CFG, "len(checkpoints)", "int")
    V.set("design.step_early", ck[0], CFG, "checkpoints[0]", "int")
    V.set("design.step_mid", ck[1], CFG, "checkpoints[1]", "int")
    V.set("design.checkpoints_planned", grab(inp.prereg, r"\| Checkpoints \| steps ([^|]+?) \|", "planned checkpoints"),
          PRE, "section 3 table")
    V.set("design.n_checkpoints_planned", 6, PRE, "section 3 table", "int")
    V.set("design.eval_n_rho", n_(cfg["eval_n_per_rho"]), CFG, "eval_n_per_rho", "int")
    V.set("design.eval_n_prior", n_(cfg["eval_n_prior"]), CFG, "eval_n_prior", "int")
    V.set("design.eval_pairs_rho", n_(cfg["eval_n_per_rho"] * 40), CFG, "eval_n_per_rho x 40 origins", "int")
    V.set("design.eval_pairs_prior", n_(cfg["eval_n_prior"] * 40), CFG, "eval_n_prior x 40 origins", "int")
    V.set("design.n_rho", len(RHOS), "rt/sim.py", "len(RHOS)", "int")
    V.set("design.rho_grid", ", ".join(r.rstrip("0").rstrip(".") if r != "0.0" else "0" for r in RHOS),
          "rt/sim.py", "RHOS")
    V.set("design.grid_points", n_(2001), "rt/evaluate.py", "Bayes rho grid (DECISIONS 2026-11-16)", "int")
    V.set("design.margin.gap", us(MARGIN["gap"], 2), "analysis/summary.py", "MARGINS.gap")
    V.set("design.margin.mse", f"{MARGIN['excess_mse_pct']:.0f}", "analysis/summary.py", "MARGINS.excess_mse_pct")
    V.set("design.h3.threshold", sg(MARGIN["gap"], 2), "analysis/hypotheses.py", "H3_MARGIN")
    V.set("design.h3.k", H["h3"]["denominator"], HYP, "h3.denominator", "int")
    V.set("design.h3.level_pct", f"{100 * (1 - 0.05 / H['h3']['denominator']):.3f}", HYP, "1 - 0.05 / h3.denominator")
    V.set("design.h3.t_adj", us(H["h3"]["bonferroni_t_n5"], 3), HYP, "h3.bonferroni_t_n5")
    V.set("design.t95.df4", us(stats.t.ppf(0.975, 4), 3), "scipy", "t.ppf(0.975, 4)")
    V.set("design.t95.df2", us(stats.t.ppf(0.975, 2), 3), "scipy", "t.ppf(0.975, 2)")
    V.set("design.n_verdicts_h1", len(H["h1"]["rows"]), HYP, "len(h1.rows)", "int")
    V.set("design.conv_tol_pct", f"{100 * cfg['convergence']['rel_tol']:g}", CFG, "convergence.rel_tol")
    V.set("design.b.a", f"{3:g}", "rt/sim.py", "B_PRIOR.a")
    V.set("design.b.b", f"{2:g}", "rt/sim.py", "B_PRIOR.b")
    V.set("design.b.k", f"{25:g}", "rt/sim.py", "B_PRIOR.k")
    V.set("design.runs.configured", n_planned, "rt/sweep.py", "len(grid(cfg))", "int")
    V.set("design.runs.configured_a", n_fam["A"], "rt/sweep.py", "family A cells", "int")
    V.set("design.runs.configured_b", n_fam["B"], "rt/sweep.py", "family B cells", "int")
    cov = H["coverage"]
    V.set("runs.planned", cov["planned"], HYP, "coverage.planned", "int")
    V.set("runs.complete", cov["complete"], HYP, "coverage.complete", "int")
    V.set("runs.not_run_by_design", len(cov["not_run_by_design"]), HYP, "len(coverage.not_run_by_design)", "int")
    V.set("runs.missing", len(cov["missing"]), HYP, "len(coverage.missing)", "int")
    V.set("runs.incomplete", len(cov["incomplete"]), HYP, "len(coverage.incomplete)", "int")
    n_primary = sum(1 for r in H["runs"] if r["family"] == "A" and r["size"] == "l")
    V.set("runs.primary", n_primary, HYP, "runs with family A, size l", "int")
    V.set("runs.m_seeds", 3, "analysis/summary.py", "PLAN_A size m", "int")
    V.set("runs.b_seeds", 3, "analysis/summary.py", "PLAN_A family B", "int")

    # -- pre-registration binding
    V.set("prereg.code_hash", inp.gate["code_hash"], "results/gate.json", "code_hash")
    V.set("prereg.code_hash_short", inp.gate["code_hash"][:8], "results/gate.json", "code_hash[:8]")
    V.set("prereg.signoff_date", long_date(grab(inp.decisions, r"## (2026-\d\d-\d\d): owner sign-off", "sign-off date")),
          DEC, "entry: owner sign-off", "date")
    tg = tags(inp)
    for t in tg:
        k = "prereg.tag." + t["name"].replace("prereg-", "").replace(".", "")
        V.set(k + ".name", t["name"], "git", f"tag {t['name']}")
        V.set(k + ".commit", t["commit"][:7], "git", f"tag {t['name']} commit")
        V.set(k + ".utc", t["utc"], "git", f"tag {t['name']} tagger date, UTC")
        V.set(k + ".time", t["utc"][11:], "git", f"tag {t['name']} tagger time, UTC")
    V.set("prereg.first_tag", "prereg-v1", "git", "tag")
    V.set("prereg.last_tag", "prereg-v1.4", "git", "tag")
    V.set("prereg.hash_v1_short", grab(inp.decisions, r"GATE PASS at code hash `(\w{8})", "v1 code hash"),
          DEC, "entry: owner sign-off")

    # -- run timing (ledgers)
    L = ledgers(inp.root)
    L["start"] = pd.to_datetime(L.start_iso, utc=True)
    L["end"] = pd.to_datetime(L.end_iso, utc=True)
    first = L.sort_values("start").iloc[0]
    V.set("ledger.n_rows", len(L), "results/ledger.csv; results/cloud/ledger*.csv", "rows", "int")
    V.set("ledger.n_mps", int((L.device == "mps").sum()), "results/ledger.csv", "device == mps", "int")
    V.set("ledger.n_cuda", int((L.device == "cuda").sum()), "results/cloud/ledger*.csv", "device == cuda", "int")
    V.set("ledger.n_failed", int((L.returncode != 0).sum()), "ledgers", "returncode != 0", "int")
    V.set("ledger.first_start", first.start.strftime("%Y-%m-%d %H:%M"), "results/ledger.csv", "min start_iso")
    V.set("ledger.first_start_time", first.start.strftime("%H:%M"), "results/ledger.csv", "min start_iso")
    V.set("ledger.first_end_time", first.end.strftime("%H:%M"), "results/ledger.csv", "end of first run")
    V.set("ledger.first_cell", first.cell_id, "results/ledger.csv", "first run")
    V.set("ledger.last_end", L.end.max().strftime("%Y-%m-%d %H:%M"), "ledgers", "max end_iso")
    V.set("ledger.hours_mps", us(L[L.device == "mps"].seconds.sum() / 3600, 1), "results/ledger.csv", "sum seconds / 3600")
    V.set("ledger.hours_cuda", us(L[L.device == "cuda"].seconds.sum() / 3600, 1), "results/cloud/ledger*.csv", "sum seconds / 3600")

    # -- cost and budget (prose facts recorded in DECISIONS and PREREG)
    d = inp.decisions
    V.set("cost.total_usd", grab(d, r"at \$0\.35/h: about \$([\d.]+) over four instances", "total spend"), DEC, "entry: sweep spend")
    V.set("cost.rate_usd", grab(d, r"estimated from instance time at \$([\d.]+)/h", "hourly rate"), DEC, "entry: sweep spend")
    V.set("cost.n_instances", "four", DEC, "entry: sweep spend")
    inst = grab(d, r"over four instances\s*\(([^)]*)\)", "per-instance spend")
    V.set("cost.instances_usd", ", ".join(re.findall(r"[\d.]+", inst)), DEC, "entry: sweep spend")
    V.set("cost.hours", grab(d, r"~(\d+) instance-hours, pilot included", "instance hours"), DEC, "entry: sweep spend")
    V.set("cost.sweep_cap_usd", grab(d, r"over the \$(\d+)\s+sweep cap and", "sweep cap"), DEC, "entry: sweep spend")
    V.set("cost.cloud_cap_usd", grab(inp.prereg, r"Cloud spend is capped at \$(\d+)", "cloud cap"), PRE, "section 10")
    V.set("cost.credit_usd", grab(inp.prereg, r"of the \$(\d+) Thunder Compute credit", "credit"), PRE, "section 10")
    V.set("cost.hard_limit_usd", grab(d, r"overall hard limit of \$(\d+)", "hard limit"), DEC, "entry: sweep spend")
    V.set("cost.lost_hours", grab(d, r"about (\d+) GPU-hours of work after", "lost GPU-hours"), DEC, "entry: sweep spend")
    V.set("cost.pilot_usd", grab(d, r"\(pilot ~\$([\d.]+)\)", "pilot cost"), DEC, "entry: deviation prereg-v1.1")
    V.set("cost.pilot_minutes", grab(d, r"19:15:49 UTC \((\d+) min\)", "pilot minutes"), DEC, "entry: cloud pilot")
    V.set("cost.projected_hours", grab(d, r"projected the configured grid at ~(\d+) GPU-hours", "projection"), DEC, "entry: deviation prereg-v1.1")
    V.set("cost.sweep_hours", f"{float(V.get('cost.sweep_cap_usd')) / float(V.get('cost.rate_usd')):.0f}", DEC,
          "sweep cap / hourly rate (12 / 0.35), GPU-hours")
    V.set("cost.total_with_pilot_usd", f"{float(V.get('cost.total_usd')) + float(V.get('cost.pilot_usd')):.2f}", DEC,
          "total over the four sweep instances plus the pilot estimate, if the pilot was billed separately")
    V.set("runs.n_resumed", "12", DEC, "entry: timing of deviations (Twelve runs were resumed)", "int")
    grab(d, r"(Twelve) runs were resumed", "resumed runs")
    V.set("runs.n_lost_ckpt", "6", DEC, "entry: timing of deviations (A-l-w8-s0 to s4 and A-l-w4-s4)", "int")
    grab(d, r"Checkpoints of (A-l-w8-s0 to s4 and A-l-w4-s4)", "lost checkpoints")
    V.set("tf32.max_mse_shift", grab(d, r"moves excess error by up to\s+([\d.]+) points", "TF32 excess shift"), DEC, "entry: timing of deviations")
    V.set("tf32.max_gap_shift", "0.0002", DEC, "entry: timing of deviations (2e-4)")
    grab(d, r"the gap by up to (2e-4)", "TF32 gap shift")
    V.set("timing.analysis_commit", grab(d, r"code was\s+first committed at (\d\d:\d\d)", "analysis commit time"), DEC, "entry: timing of deviations")
    V.set("timing.primary_metrics", grab(d, r"had metrics files by (2026-11-18 \d\d:\d\d)", "first primary metrics"), DEC, "entry: timing of deviations")

    # -- pre-freeze exposure (PREREG section 9)
    p = inp.prereg
    V.set("prefreeze.linear_r1_mse", grab(p, r"left the linear-head model at (\d+)% excess error at rho = 1", "linear-head failure"), PRE, "section 9")
    V.set("prefreeze.linear_r1_mse_w4", grab(p, r"\((\d+)% in the W = 4 run\)", "linear-head failure, W = 4"), PRE, "section 9")
    V.set("prefreeze.affine_r1_mse", grab(p, r"the affine head\s+removed it \(([\d.]+)% and", "affine head at rho = 1"), PRE, "section 9")
    V.set("prefreeze.affine_r1_mse_w4", grab(p, r"removed it \([\d.]+% and ([\d.]+)%\)", "affine head at rho = 1, W = 4"), PRE, "section 9")
    V.set("prefreeze.steps", "3,000", PRE, "section 9 (trained 3,000 steps)")
    V.set("prefreeze.rho0_low", grab(p, r"overstated persistence at rho = 0 against Bayes \(\+([\d.]+) to", "rho = 0 residual, low"), PRE, "section 8")
    V.set("prefreeze.rho0_high", grab(p, r"against Bayes \(\+[\d.]+ to \+([\d.]+),", "rho = 0 residual, high"), PRE, "section 8")

    # -- H1
    h1 = H["h1"]
    V.set("h1.decision", DECISION_TEXT[h1["decision"]], HYP, "h1.decision", "decision")
    V.set("h1.n_equivalent", sum(r["verdict"] == "equivalent" for r in h1["rows"]), HYP, "h1.rows[verdict == equivalent]", "int")
    V.set("h1.n_total", len(h1["rows"]), HYP, "len(h1.rows)", "int")
    for col, nd in (("excess_mse_pct", 3), ("gap", 4)):
        rows = [inp.row("l", "full", r, col) for r in RHOS]
        ck_ = "mse" if col == "excess_mse_pct" else "gap"
        V.set(f"h1.{ck_}.min_lo", sg(min(r.lo for r in rows), nd), SUM, f"A,l,full,30000,h=1,bayes,{col}: min lo", "coef")
        V.set(f"h1.{ck_}.max_hi", sg(max(r.hi for r in rows), nd), SUM, f"A,l,full,30000,h=1,bayes,{col}: max hi", "coef")
        e, where = widest_end(rows)
        V.set(f"h1.{ck_}.max_abs_end", us(abs(e), nd), SUM, f"A,l,full,30000,h=1,bayes,{col}: widest interval end", "coef")
        V.set(f"h1.{ck_}.max_abs_end_rho", where, SUM, f"rho of the widest {col} interval end")
        V.set(f"h1.{ck_}.margin_ratio", f"{MARGIN[col] / abs(e):.0f}", SUM, f"margin / widest {col} interval end")
        for rho in RHO_KEYS:
            r = inp.row("l", "full", rho, col)
            base = f"h1.{rk(rho)}.{ck_}"
            V.set(base + ".mean", sg(r.mean, nd), SUM, f"A,l,full,30000,{rho},1,bayes,{col}: mean", "coef")
            V.set(base + ".lo", sg(r.lo, nd), SUM, f"A,l,full,30000,{rho},1,bayes,{col}: lo", "coef")
            V.set(base + ".hi", sg(r.hi, nd), SUM, f"A,l,full,30000,{rho},1,bayes,{col}: hi", "coef")

    # -- H2
    all_rows = {c: [] for c in COLS}
    for w in H2_WINDOWS:
        blk = H["h2"]["windows"][w]
        V.set(f"h2.{wk(w)}.decision", DECISION_TEXT[blk["decision"]], HYP, f"h2.windows.{w}.decision", "decision")
        V.set(f"h2.{wk(w)}.n_equivalent", sum(r["verdict"] == "equivalent" for r in blk["rows"]), HYP,
              f"h2.windows.{w}.rows[verdict == equivalent]", "int")
        for col, nd in (("excess_mse_pct", 3), ("gap", 4)):
            ck_ = "mse" if col == "excess_mse_pct" else "gap"
            rows = [inp.row("l", w, r, col) for r in RHOS]
            all_rows[col] += [(w, r) for r in rows]
            e, where = widest_end(rows)
            V.set(f"h2.{wk(w)}.{ck_}.widest_end", sg(e, nd), SUM, f"A,l,{w},30000,h=1,window_bayes,{col}: widest interval end", "coef")
            V.set(f"h2.{wk(w)}.{ck_}.widest_end_rho", where, SUM, f"rho of that end")
            for rho in RHO_KEYS:
                r = inp.row("l", w, rho, col)
                base = f"h2.{wk(w)}.{rk(rho)}.{ck_}"
                V.set(base + ".mean", sg(r.mean, nd), SUM, f"A,l,{w},30000,{rho},1,window_bayes,{col}: mean", "coef")
                V.set(base + ".lo", sg(r.lo, nd), SUM, f"A,l,{w},30000,{rho},1,window_bayes,{col}: lo", "coef")
                V.set(base + ".hi", sg(r.hi, nd), SUM, f"A,l,{w},30000,{rho},1,window_bayes,{col}: hi", "coef")
    V.set("h2.n_windows", len(H2_WINDOWS), HYP, "len(h2.windows)", "int")
    V.set("h2.n_total", 12, HYP, "len(h2.windows.W.rows)", "int")
    V.set("h2.n_equivalent_all", sum(sum(r["verdict"] == "equivalent" for r in H["h2"]["windows"][w]["rows"]) for w in H2_WINDOWS),
          HYP, "equivalent verdicts over the four windows", "int")
    V.set("h2.n_total_all", 12 * len(H2_WINDOWS), HYP, "verdicts over the four windows", "int")
    for col, nd in (("excess_mse_pct", 3), ("gap", 4)):
        ck_ = "mse" if col == "excess_mse_pct" else "gap"
        w_best, r_best, e_best = "", None, 0.0
        for w, r in all_rows[col]:
            for e in (r.lo, r.hi):
                if abs(e) > abs(e_best):
                    w_best, r_best, e_best = w, r, float(e)
        V.set(f"h2.all.{ck_}.widest_end", us(abs(e_best), nd), SUM, f"size l, W in 2..16, {col}: widest interval end", "coef")
        V.set(f"h2.all.{ck_}.widest_end_w", w_best, SUM, "window of that end")
        V.set(f"h2.all.{ck_}.widest_end_rho", r_best.rho, SUM, "rho of that end")
        V.set(f"h2.all.{ck_}.margin_share_pct", f"{100 * abs(e_best) / MARGIN[col]:.0f}", SUM, "widest end as a percentage of the margin")

    # -- the rho = 0 residual (exploratory)
    r0 = [inp.row("l", w, "0.0", "gap") for w in WINDOWS]
    V.set("rho0.n_windows", len(r0), SUM, "A,l,W,30000,0.0,1,matching bench,gap", "int")
    V.set("rho0.n_excl_zero", sum(r.lo > 0 for r in r0), SUM, "count with lo > 0", "int")
    V.set("rho0.min_mean", sg(min(r.mean for r in r0)), SUM, "min mean", "coef")
    V.set("rho0.max_mean", sg(max(r.mean for r in r0)), SUM, "max mean", "coef")
    V.set("rho0.max_hi", sg(max(r.hi for r in r0)), SUM, "max hi", "coef")
    r0w = [inp.row("l", w, "0.0", "gap") for w in H2_WINDOWS]
    V.set("rho0.windowed.min_mean", us(min(r.mean for r in r0w), 3), SUM, "min mean, W in 2..16", "coef")
    V.set("rho0.windowed.max_mean", us(max(r.mean for r in r0w), 3), SUM, "max mean, W in 2..16", "coef")

    # -- H3
    h3 = H["h3"]
    combos = h3["combos"]
    V.set("h3.decision", DECISION_TEXT[h3["decision"]], HYP, "h3.decision", "decision")
    V.set("h3.statement", h3["statement"], HYP, "h3.statement", "decision")
    V.set("h3.k95", h3["k_positive_95"], HYP, "h3.k_positive_95", "int")
    V.set("h3.k_adjusted", h3["k_positive_adjusted"], HYP, "h3.k_positive_adjusted", "int")
    V.set("h3.denominator", h3["denominator"], HYP, "h3.denominator", "int")
    V.set("h3.max_hi", sg(max(c["hi"] for c in combos)), HYP, "max over h3.combos of hi", "coef")
    V.set("h3.max_mean", sg(max(c["mean"] for c in combos)), HYP, "max over h3.combos of mean", "coef")
    V.set("h3.min_mean", sg(min(c["mean"] for c in combos)), HYP, "min over h3.combos of mean", "coef")
    V.set("h3.max_lo", sg(max(c["lo"] for c in combos)), HYP, "max over h3.combos of lo", "coef")
    V.set("h3.max_lo_adj", sg(max(c["lo_adj"] for c in combos)), HYP, "max over h3.combos of lo_adj", "coef")
    V.set("h3.min_lo_adj", sg(min(c["lo_adj"] for c in combos)), HYP, "min over h3.combos of lo_adj", "coef")
    V.set("h3.n_mean_positive", sum(c["mean"] > 0 for c in combos), HYP, "count of h3.combos with mean > 0", "int")
    V.set("h3.n_incl_zero", sum(c["lo"] < 0 < c["hi"] for c in combos), HYP, "count of h3.combos with lo < 0 < hi", "int")
    V.set("h3.threshold_over_max_hi", f"{MARGIN['gap'] / max(c['hi'] for c in combos):.0f}", HYP, "0.02 / max hi")
    hi_adj = max(c["mean"] + h3["bonferroni_t_n5"] * c["sd"] / math.sqrt(5) for c in combos)
    V.set("h3.max_hi_adj", sg(hi_adj), HYP, "max over h3.combos of mean + t_adj sd / sqrt(5)", "coef")
    for c in combos:
        base = f"h3.{wk(c['window'])}.{rk(c['rho'])}"
        for f in ("mean", "lo", "hi", "lo_adj"):
            V.set(f"{base}.{f}", sg(c[f]), HYP, f"h3.combos[window={c['window']},rho={c['rho']}].{f}", "coef")
    V.set("h3.other.k95", h3["other_sizes_k_positive_95"], HYP, "h3.other_sizes_k_positive_95", "int")
    V.set("h3.other.denominator", h3["other_sizes_denominator"], HYP, "h3.other_sizes_denominator", "int")
    V.set("flagged.n", len(H["flagged"]), HYP, "len(flagged)", "int")

    # -- exploratory: size
    for s in SIZES:
        tot = {"equivalent": 0, "different": 0, "inconclusive": 0}
        for w in WINDOWS:
            c = counts(inp, s, w)
            for k, v in c.items():
                tot[k] += v
                V.set(f"size.{s}.{wk(w)}.{k}", v, SUM, f"A,{s},{w},30000,h=1,matching bench: verdict == {k}", "int")
        for k, v in tot.items():
            V.set(f"size.{s}.total.{k}", v, SUM, f"A,{s},all windows,30000,h=1: verdict == {k}", "int")
    V.set("size.n_per_size", 12 * len(WINDOWS), SUM, "12 verdicts x 5 windows", "int")
    for rho in ("0.0", "0.6", "0.8"):
        r = inp.row("xs", "full", rho, "gap")
        V.set(f"size.xs.full.{rk(rho)}.gap.mean", sg(r.mean, 3), SUM, f"A,xs,full,30000,{rho},1,bayes,gap: mean", "coef")
    xs_h3 = [c for c in h3["other_sizes"]["xs"]["combos"]]
    V.set("size.xs.h3.n_mean_negative", sum(c["mean"] < 0 for c in xs_h3), HYP, "h3.other_sizes.xs.combos with mean < 0", "int")
    V.set("size.xs.h3.min_mean", sg(min(c["mean"] for c in xs_h3), 3), HYP, "min mean over h3.other_sizes.xs.combos", "coef")
    V.set("size.xs.h3.max_mean", sg(max(c["mean"] for c in xs_h3), 3), HYP, "max mean over h3.other_sizes.xs.combos", "coef")
    xs_rows = [inp.row("xs", w, rho, "gap") for w in WINDOWS for rho in RHOS]
    V.set("size.xs.max_gap_mean", sg(max(r.mean for r in xs_rows), 3), SUM, "A,xs,30000,h=1,gap: max mean", "coef")
    V.set("size.xs.min_gap_mean", sg(min(r.mean for r in xs_rows), 3), SUM, "A,xs,30000,h=1,gap: min mean", "coef")
    xs_mse = [inp.row("xs", w, rho, "excess_mse_pct") for w in WINDOWS for rho in RHOS]
    V.set("size.xs.max_mse_mean", us(max(r.mean for r in xs_mse), 1), SUM, "A,xs,30000,h=1,excess_mse_pct: max mean", "coef")

    # -- exploratory: training traces
    for step in STEPS:
        for w in WINDOWS:
            V.set(f"trace.s{step}.{wk(w)}.equivalent", counts(inp, "l", w, step=step)["equivalent"], SUM,
                  f"A,l,{w},{step},h=1,matching bench: verdict == equivalent", "int")
    early = [3000, 10000]
    V.set("trace.windowed.max_equivalent_early",
          max(counts(inp, "l", w, step=st)["equivalent"] for w in H2_WINDOWS for st in early), SUM,
          "max over W in 2..16 and steps 3000, 10000 of equivalent verdicts", "int")
    V.set("trace.windowed.max_mse_early",
          f"{max(inp.row('l', w, r, 'excess_mse_pct', step=st).mean for w in H2_WINDOWS for st in early for r in RHOS):.0f}",
          SUM, "max mean excess error, W in 2..16, steps 3000 and 10000, grid rho", "coef")
    for st in early:
        g = [inp.row("l", w, r, "gap", step=st) for w in H2_WINDOWS for r in ("0.6", "0.8")]
        V.set(f"trace.s{st}.h3.n_negative", sum(x.mean < 0 for x in g), SUM, f"step {st}: H3 rows with mean gap < 0", "int")
        V.set(f"trace.s{st}.h3.min_mean", sg(min(x.mean for x in g), 3), SUM, f"step {st}: min mean gap on H3 rows", "coef")
        V.set(f"trace.s{st}.h3.max_mean", sg(max(x.mean for x in g), 4 if st == 10000 else 3), SUM, f"step {st}: max mean gap on H3 rows", "coef")
        V.set(f"trace.s{st}.h3.n_inconclusive", sum(x.verdict == "inconclusive" for x in g), SUM, f"step {st}: inconclusive H3 rows", "int")
    gf = [inp.row("l", "full", r, "gap", step=st) for st in early for r in ("0.6", "0.8")]
    V.set("trace.full.h3.min_mean", sg(min(x.mean for x in gf), 3), SUM, "full window, steps 3000 and 10000, rho 0.6 and 0.8: min mean gap", "coef")
    V.set("trace.full.h3.max_mean", sg(max(x.mean for x in gf), 3), SUM, "same: max mean gap", "coef")
    V.set("trace.full.h3.n_incl_zero", sum(x.lo < 0 < x.hi for x in gf), SUM, "same: intervals including zero", "int")
    V.set("trace.full.h3.n", len(gf), SUM, "same: rows", "int")
    lruns = [r for r in H["runs"] if r["family"] == "A" and r["size"] == "l"]
    V.set("conv.l.n_converged", sum(r["converged"] for r in lruns), HYP, "runs: family A, size l, converged", "int")
    V.set("conv.l.n_runs", len(lruns), HYP, "runs: family A, size l", "int")
    V.set("conv.all.n_converged", sum(r["converged"] for r in H["runs"]), HYP, "runs: converged", "int")

    # -- exploratory: horizons 2-6
    hv = {"equivalent": 0, "different": 0, "inconclusive": 0}
    gmax = mmax = 0.0
    for w in WINDOWS:
        c = counts(inp, "l", w, hs=range(2, 7))
        for k in hv:
            hv[k] += c[k]
        for h in range(2, 7):
            for rho in RHOS:
                gmax = max(gmax, abs(inp.row("l", w, rho, "gap", h=h).mean))
                mmax = max(mmax, abs(inp.row("l", w, rho, "excess_mse_pct", h=h).mean))
    V.set("horizons.n_verdicts", sum(hv.values()), SUM, "A,l,all windows,30000,h=2..6,matching bench", "int")
    V.set("horizons.n_equivalent", hv["equivalent"], SUM, "same: verdict == equivalent", "int")
    V.set("horizons.max_abs_gap_mean", us(gmax), SUM, "same: max |mean gap|", "coef")
    V.set("horizons.max_abs_mse_mean", us(mmax, 2), SUM, "same: max |mean excess error|", "coef")

    # -- exploratory: error on revision and kappa (seed level, from results/metrics)
    E = eor_table(inp)
    e1 = E[(E.h == 1) & (E.rho != "prior")]
    V.set("eor.h1.max_abs_diff", us(e1["diff"].abs().max()), "results/metrics", "size l, step 30000, h=1: max |mean(model b - benchmark b)|", "coef")
    V.set("eor.h1.n_rows", len(e1), "results/metrics", "5 windows x 6 rho", "int")
    V.set("eor.h1.n_excl_zero", int(((e1.lo > 0) | (e1.hi < 0)).sum()), "results/metrics", "rows whose 95% interval excludes zero", "int")
    eall = E[E.rho != "prior"]
    V.set("eor.all.max_abs_diff", us(eall["diff"].abs().max()), "results/metrics", "h=1..5: max |mean difference|", "coef")
    V.set("eor.all.n_rows", len(eall), "results/metrics", "5 windows x 5 horizons x 6 rho", "int")
    for w in ("4", "full"):
        for rho in ("0.0", "0.8"):
            x = E[(E.window == w) & (E.h == 1) & (E.rho == rho)].iloc[0]
            V.set(f"eor.h1.{wk(w)}.{rk(rho)}.bench", sg(x.bench_b, 3), "results/metrics", f"A,l,{w},30000,{rho},h=1: mean bench_eor_b", "coef")
            V.set(f"eor.h1.{wk(w)}.{rk(rho)}.model", sg(x.model_b, 3), "results/metrics", f"A,l,{w},30000,{rho},h=1: mean eor_b", "coef")
    V.set("eor.gate.a", sg(inp.gate["checks"]["benchmark"]["families"]["A"]["eor_b_h1"], 4), "results/gate.json", "checks.benchmark.families.A.eor_b_h1", "coef")
    V.set("eor.gate.b", sg(inp.gate["checks"]["benchmark"]["families"]["B"]["eor_b_h1"], 4), "results/gate.json", "checks.benchmark.families.B.eor_b_h1", "coef")
    K = kappa_table(inp)
    kf = K[(K.window == "full") & (K.rho != "prior")]
    V.set("kappa.full.max_abs", us(kf["mean"].abs().max()), "results/metrics", "A,l,full,30000,h=1,bayes: max |mean kappa|", "coef")

    # -- benchmarks alone (Family A, h = 1)
    B = pd.DataFrame(H["benchmarks"])
    for r in B.itertuples():
        name = r.bench if r.bench != "window_bayes" else f"w{r.window}"
        V.set(f"bench.{name}.{rk(r.rho)}", us(r.implied_persistence, 2 if r.rho != "prior" else 3), HYP,
              f"benchmarks[rho={r.rho},bench={r.bench},window={r.window}].implied_persistence", "coef")
    bb = {(r.bench, r.window, r.rho): r.implied_persistence for r in B.itertuples()}
    dmax = max(bb[("window_bayes", w, rho)] - bb[("bayes", "-", rho)] for w in H2_WINDOWS for rho in RHOS)
    V.set("bench.max_wb_minus_bayes", us(dmax, 2), HYP, "max over W and grid rho of window-Bayes minus Bayes implied persistence", "coef")
    V.set("bench.n_wb_below_truth_high", sum(bb[("window_bayes", w, rho)] < float(rho) for w in H2_WINDOWS for rho in ("0.6", "0.8")),
          HYP, "window-Bayes implied persistence below rho at rho = 0.6, 0.8", "int")

    # -- human curve and Family B overlay
    hum = {f"{h['rho']:.1f}": h for h in H["human"]}
    ex = []
    for rho, h in hum.items():
        lo, hi = h["implied_rho"] - 1.96 * h["implied_rho_se"], h["implied_rho"] + 1.96 * h["implied_rho_se"]
        V.set(f"human.{rk(rho)}.ip", us(h["implied_rho"], 2), HYP, f"human[rho={rho}].implied_rho", "coef")
        V.set(f"human.{rk(rho)}.lo", us(lo, 2), HYP, f"human[rho={rho}]: implied_rho - 1.96 se", "coef")
        V.set(f"human.{rk(rho)}.hi", us(hi, 2), HYP, f"human[rho={rho}]: implied_rho + 1.96 se", "coef")
        if float(rho) <= 0.8:
            ex.append(h["implied_rho"] - float(rho))
    V.set("human.excess_min", us(min(ex), 2), HYP, "min over rho <= 0.8 of implied_rho - rho", "coef")
    V.set("human.excess_max", us(max(ex), 2), HYP, "max over rho <= 0.8 of implied_rho - rho", "coef")
    V.set("human.participants_min", min(h["participants"] for h in H["human"]), HYP, "min human.participants", "int")
    V.set("human.participants_max", max(h["participants"] for h in H["human"]), HYP, "max human.participants", "int")
    fb = {}
    for w in ("full", "4"):
        for rho in RHO_KEYS:
            r = inp.row("l", w, rho, "gap", family="B")
            fb[(w, rho)] = r
            V.set(f"fb.{wk(w)}.{rk(rho)}.model", us(r.implied_persistence, 3), SUM, f"B,l,{w},30000,{rho},1,matching bench: implied_persistence", "coef")
            V.set(f"fb.{wk(w)}.{rk(rho)}.bench", us(r.bench_implied_persistence, 3), SUM, f"B,l,{w},30000,{rho},1: bench_implied_persistence", "coef")
            V.set(f"fb.{wk(w)}.{rk(rho)}.bench2", us(r.bench_implied_persistence, 2), SUM, f"B,l,{w},30000,{rho},1: bench_implied_persistence", "coef")
    fbrows = [inp.row("l", w, rho, col, family="B") for w in ("full", "4") for rho in RHO_KEYS for col in COLS]
    V.set("fb.n_verdicts", len(fbrows), SUM, "B,l,{full,4},30000,h=1,matching bench: rows", "int")
    V.set("fb.n_equivalent", sum(r.verdict == "equivalent" for r in fbrows), SUM, "same: verdict == equivalent", "int")
    V.set("fb.max_abs_gap", us(max(abs(r.mean) for r in fbrows if r.column == "gap")), SUM, "same: max |mean gap|", "coef")
    exc = [r for r in fbrows if r.verdict != "equivalent"]
    assert len(exc) == 1, "paper prose assumes exactly one Family B exception"
    V.set("fb.exception.window", exc[0].window, SUM, "the non-equivalent Family B row: window")
    V.set("fb.exception.rho", exc[0].rho.rstrip("0").rstrip("."), SUM, "the non-equivalent Family B row: rho")
    V.set("fb.exception.mean", sg(exc[0].mean, 2), SUM, "the non-equivalent Family B row: mean", "coef")
    V.set("fb.exception.verdict", exc[0].verdict, SUM, "the non-equivalent Family B row: verdict")
    V.set("fb.exception.measure", MEASURE[exc[0].column], SUM, "the non-equivalent Family B row: column")
    incl = [rho for rho in RHOS if (hum[rho]["implied_rho"] - 1.96 * hum[rho]["implied_rho_se"]
                                    <= fb[("4", rho)].bench_implied_persistence
                                    <= hum[rho]["implied_rho"] + 1.96 * hum[rho]["implied_rho_se"])]
    V.set("overlay.n_human_ci_incl_w4", len(incl), HYP + "; " + SUM, "grid rho whose human 95% interval includes the W = 4 window-Bayes curve", "int")
    V.set("overlay.first_rho_incl_w4", incl[0].rstrip("0").rstrip("."), HYP + "; " + SUM, "smallest such rho")
    above = [rho for rho in RHOS if hum[rho]["implied_rho"] > fb[("4", rho)].bench_implied_persistence]
    V.set("overlay.rhos_human_above_w4", ", ".join(a.rstrip("0").rstrip(".") for a in above), HYP + "; " + SUM,
          "grid rho where the human point estimate is above the W = 4 window-Bayes curve")
    dc = pd.DataFrame(H["design_check"])
    V.set("aklmt.innov_sd_min", us(dc.innov_sd.min(), 1), HYP, "min design_check.innov_sd", "coef")
    V.set("aklmt.innov_sd_max", us(dc.innov_sd.max(), 1), HYP, "max design_check.innov_sd", "coef")

    # -- survey comparison
    spf = H["spf"]
    rows = spf["rows"]
    for r in rows:
        base = f"spf.{r['variable'].lower()}.{wk(r['window'])}"
        V.set(base + ".model", sg(r["b_model_mean"], 2), HYP, f"spf.rows[{r['variable']},{r['window']}].b_model_mean", "coef")
        V.set(base + ".survey", sg(r["b_survey"], 2), HYP, f"spf.rows[{r['variable']},{r['window']}].b_survey", "coef")
        V.set(base + ".quarters", r["T"], HYP, f"spf.rows[{r['variable']},{r['window']}].T", "int")
    V.set("spf.n_cells", len(rows), HYP, "len(spf.rows)", "int")
    V.set("spf.n_model_negative", sum(r["b_model_mean"] < 0 for r in rows), HYP, "spf.rows with b_model_mean < 0", "int")
    surv = {r["variable"]: r["b_survey"] for r in rows}
    V.set("spf.n_variables", len(surv), HYP, "distinct spf.rows.variable", "int")
    V.set("spf.n_survey_positive", sum(v > 0 for v in surv.values()), HYP, "variables with b_survey > 0", "int")
    V.set("spf.n_same_sign", sum((r["b_model_mean"] > 0) == (r["b_survey"] > 0) for r in rows), HYP, "cells where model and survey b share a sign", "int")
    om = [o for o in spf["omitted"] if "variable-quarters" in o["reason"]]
    V.set("spf.omitted.cell", om[0]["cell"], HYP, "spf.omitted (per-cell rule)")
    V.set("spf.omitted.pct", grab(om[0]["reason"], r"([\d.]+)% of its", "omitted share"), HYP, "spf.omitted reason")
    V.set("spf.cell_limit_pct", grab(om[0]["reason"], r"limit (\d+)% per cell", "per-cell limit"), HYP, "spf.omitted reason")
    V.set("spf.seeds", rows[0]["n_seeds"], HYP, "spf.rows[0].n_seeds", "int")

    # -- further design constants and verbatim decision wording (PREREG sections 6 and 7)
    V.set("design.level_pct", "95", PRE, "section 6: 95% Student-t interval", "int")
    V.set("design.h3.rho_lo", "0.6", "analysis/hypotheses.py", "H3_RHOS[0]")
    V.set("design.h3.rho_hi", "0.8", "analysis/hypotheses.py", "H3_RHOS[1]")
    V.set("design.head_outputs", 2 * cfg["horizons"], "rt/model.py", "2 x HORIZONS", "int")
    V.set("runs.a", sum(r["family"] == "A" for r in H["runs"]), HYP, "runs with family A", "int")
    V.set("runs.b", sum(r["family"] == "B" for r in H["runs"]), HYP, "runs with family B", "int")
    q = lambda t: re.sub(r'"([^"]*)"', "“\\1”", t.replace("**", ""))          # noqa: E731
    V.set("prereg.h1.rule", q(grab(p, r"(H1 is \*\*supported\*\* if all 12 are \"equivalent\"\.)", "H1 rule")), PRE, "section 7, H1 decision", "verbatim")
    V.set("prereg.h2.rule", q(grab(p, r"- (All 12 \"equivalent\": \*\*rational given its information\.\*\* Everything the window-W network gets \"wrong\" relative to full Bayes is the information limit\.)", "H2 rule")),
          PRE, "section 7, H2 decision", "verbatim")
    V.set("prereg.h3.rule", q(grab(p, r"(H3 is \*\*supported\*\* only if at least one of the 8 primary combinations is positive after a Bonferroni adjustment for 8)", "H3 rule")),
          PRE, "section 7, H3 rule", "verbatim")
    V.set("prereg.h3.positive", q(grab(p, r"(A combination is \*\*positive\*\* if the lower end of the 95% interval of the mean gap is above \+0\.02\.)", "H3 positive")),
          PRE, "section 7, H3 rows", "verbatim")
    V.set("prereg.h3.report", q(grab(p, r"reported as (\"k of 8 positive at 95%, none after adjustment\")", "H3 reporting form")), PRE, "section 7, H3 rule", "verbatim")
    V.set("prereg.bias_rule", q(grab(p, r"\*\*(Nothing in this study is called a bias unless it exceeds the Bayes forecaster with the same prior and the same information, at the same rho\.)\*\*", "bias rule")),
          PRE, "section 1", "verbatim")
    V.set("prereg.not_robust", q(grab(p, r"reported as \*\*(\"not robust to training length\")\*\*", "training-length wording")), PRE, "section 6", "verbatim")
    V.set("prereg.not_tested", q(grab(p, r"reported as \*\*(\"different at 30,000 steps; not tested for training length\")\*\*", "not-tested wording")), PRE, "section 6", "verbatim")
    V.set("spf.sample", grab(d, r"UNEMP, TB3M, TN10Y; (1968Q4-2016Q4)\)", "SPF sample").replace("-", "–"), DEC, "entry: Survey comparison conventions")
    nov = (inp.root / "docs" / "novelty_check.md").read_text()
    V.set("novelty.date", long_date(grab(nov, r"\*\*Date:\*\* (2026-\d\d-\d\d)", "novelty search date")), "docs/novelty_check.md", "Date", "date")
    ex1 = e1.loc[e1["diff"].abs().idxmax()]
    V.set("eor.h1.max_w", ex1.window, "results/metrics", "window of the largest |difference| at h=1")
    V.set("eor.h1.max_rho", ex1.rho.rstrip("0").rstrip("."), "results/metrics", "rho of the largest |difference| at h=1")
    V.set("eor.h1.max_abs_diff_ex1", us(e1[e1.rho != "1.0"]["diff"].abs().max()), "results/metrics", "h=1, rho < 1: max |mean difference|", "coef")
    exa = eall.loc[eall["diff"].abs().idxmax()]
    V.set("eor.all.max_w", exa.window, "results/metrics", "window of the largest |difference|, h=1..5")
    V.set("eor.all.max_h", int(exa.h), "results/metrics", "horizon of the largest |difference|", "int")
    V.set("eor.all.max_rho", exa.rho.rstrip("0").rstrip(".") or "0", "results/metrics", "rho of the largest |difference|")
    V.set("eor.all.max_lo", sg(exa.lo, 3), "results/metrics", "its interval, lower end", "coef")
    V.set("eor.all.max_hi", sg(exa.hi, 3), "results/metrics", "its interval, upper end", "coef")
    V.set("eor.all.n_excl_zero", int(((eall.lo > 0) | (eall.hi < 0)).sum()), "results/metrics", "h=1..5: rows whose 95% interval excludes zero", "int")

    hi4 = [inp.row("l", w, r, "gap") for w in H2_WINDOWS for r in ("0.4", "0.6", "0.8", "1.0")]
    V.set("h2.rho04plus.gap.widest_end", us(abs(widest_end(hi4)[0])), SUM, "size l, W in 2..16, rho >= 0.4, gap: widest interval end", "coef")
    V.set("h3.max_sd", us(max(c["sd"] for c in combos)), HYP, "max over h3.combos of sd", "coef")
    v11 = next(t for t in tg if t["name"] == "prereg-v1.1")
    mins = (first.start - pd.Timestamp(v11["utc"], tz="UTC")).total_seconds() / 60
    V.set("timing.minutes_tag_to_first_run", f"{mins:.0f}", "git; results/ledger.csv", "first start_iso minus tagger date of prereg-v1.1, minutes")
    sig = json.loads((inp.root / "docs" / "paper" / "signature.json").read_text())
    V.set("signature.statement", sig["statement"], "docs/paper/signature.json", "statement", "verbatim")
    V.set("signature.date", long_date(sig["date"]), "docs/paper/signature.json", "date", "date")
    n_below = sum(bb[("window_bayes", w, rho)] < float(rho) for w in H2_WINDOWS for rho in ("0.6", "0.8"))
    assert n_below == 8, "prose says window-Bayes underreacts against the truth at every H3 row"

    pos = [(w, rho, inp.row("l", w, rho, "gap")) for w in WINDOWS for rho in RHOS if rho != "0.0"]
    pos = [(w, rho, r) for w, rho, r in pos if r.lo > 0]
    by_rho: dict[str, list[str]] = {}
    for w, rho, _ in pos:
        by_rho.setdefault(rho, []).append("the full window" if w == "full" else f"W = {w}")
    join = lambda xs: xs[0] if len(xs) == 1 else ", ".join(xs[:-1]) + " and " + xs[-1]      # noqa: E731
    V.set("gappos.n_other", len(pos), SUM, "size l, 30000, h=1, matching bench, gap, rho > 0: intervals with lo > 0", "int")
    V.set("gappos.other_cells", "; ".join(f"ρ = {rho} at {join(ws)}" for rho, ws in by_rho.items()), SUM, "those cells")
    V.set("gappos.other_max_mean", sg(max(r.mean for _, _, r in pos)), SUM, "largest mean among them", "coef")
    assert max(r.mean for _, _, r in pos) < max(r.mean for r in r0), "prose says the rho = 0 residual is the largest"

    # -- environment
    lock = (inp.root / "uv.lock").read_text()
    for pkg in ("torch", "numpy", "scipy", "pandas", "matplotlib", "pyarrow", "pytest"):
        V.set(f"env.{pkg}", grab(lock, rf'name = "{pkg}"\nversion = "([^"]+)"', f"{pkg} version", flat=False), "uv.lock", f"package {pkg}")
    V.set("env.python", grab((inp.root / "pyproject.toml").read_text(), r'requires-python = "([^"]+)"', "python"),
          "pyproject.toml", "requires-python")
    return V


# ---- tables -------------------------------------------------------------------------------

TABLES: list[dict] = []
FIGURES: list[dict] = []


def write_table(tid: str, body: str, caption: str, source: str, notes: str = "") -> None:
    text = (f"<!-- Generated by `{CMD}` from {source}. Do not edit. -->\n\n{body}\n\n"
            f": {caption.rstrip('.')}. {{#tbl-{tid}}}\n")
    if notes:
        text += f"\n*Notes:* {notes}\n"
    (GEN / "tables" / f"{tid}.md").write_text(text)
    TABLES.append({"id": tid, "source": source, "caption": caption, "notes": notes})


def conf_row(r, prefix: list[str]) -> list[str]:
    return prefix + [MEASURE[r.column], UNIT[r.column], sg(r.mean), us(r.sd), ci(r.lo, r.hi),
                     str(int(r.n_seeds) - 1), "95% t", f"±{MARGIN[r.column]:g}", r.verdict]


def build_tables(inp: Inputs) -> None:
    H, cfg = inp.H, inp.cfg
    SUM, HYP = "`results/summary.csv`", "`results/hypotheses.json`"
    note_sum = ("Each row is one line of `results/summary.csv`: the estimate is the mean over seeds, sd the "
                "standard deviation across seeds, and the interval the 95% Student-t interval of the mean on the "
                "stated degrees of freedom. Units: pp is percentage points of the benchmark's mean squared error; "
                "slope is units of implied persistence. Status is the pre-registered verdict: equivalent if the "
                "whole interval lies inside the margin.")

    # H1
    heads = ["ρ", "measure", "unit", "estimate", "sd", "95% CI", "df", "level", "margin", "status"]
    w_ = [5, 12, 6, 9, 8, 20, 3, 7, 7, 13]
    rows = [conf_row(inp.row("l", "full", rho, col), [rho]) for rho in RHOS for col in COLS]
    rows += [conf_row(inp.row("l", "full", "prior", col), ["prior"]) for col in COLS]
    write_table("h1-confirmatory", table(heads, rows, w_),
                "Confirmatory test of H1: the largest model with the full window against Bayes, horizon 1, "
                "step 30,000, five seeds (PREREG sections 6 and 7)", SUM,
                note_sum + " The prior rows are printed for comparison and are not part of the decision.")

    # H2
    heads2 = ["W"] + heads
    rows = [conf_row(inp.row("l", w, rho, col), [w, rho]) for w in H2_WINDOWS for rho in RHOS for col in COLS]
    write_table("h2-confirmatory", table(heads2, rows, [3] + w_),
                "Confirmatory test of H2: the largest model with window W against window-Bayes, horizon 1, "
                "step 30,000, five seeds; each window is a separate test (PREREG sections 6 and 7)", SUM, note_sum)
    rows = []
    for w in H2_WINDOWS:
        blk = H["h2"]["windows"][w]
        em, wm = widest_end([inp.row("l", w, r, "excess_mse_pct") for r in RHOS])
        eg, wg = widest_end([inp.row("l", w, r, "gap") for r in RHOS])
        rows.append([w, f"{sum(r['verdict'] == 'equivalent' for r in blk['rows'])} of {len(blk['rows'])}",
                     f"{sg(em, 3)} (ρ = {wm})", f"{sg(eg)} (ρ = {wg})", DECISION_TEXT[blk["decision"]]])
    write_table("h2-summary", table(["W", "equivalent", "widest end, excess error (pp)",
                                     "widest end, gap", "decision"], rows),
                "H2 by window: verdict counts, the 95% interval end furthest from zero for each measure, and the "
                "decision in the registered wording",
                f"{SUM}, {HYP}")

    # H3
    rows = []
    for c in H["h3"]["combos"]:
        rows.append([c["window"], c["rho"], "slope", sg(c["mean"]), us(c["sd"]), ci(c["lo"], c["hi"]),
                     sg(c["lo_adj"]), str(c["n_seeds"] - 1), sg(MARGIN["gap"], 2),
                     "yes" if c["positive_95"] else "no", "yes" if c["positive_adjusted"] else "no"])
    write_table("h3-confirmatory",
                table(["W", "ρ", "unit", "estimate", "sd", "95% CI", "adjusted lower end (99.375%)", "df",
                       "threshold", "positive at 95%", "positive after adjustment"], rows,
                      [3, 4, 6, 9, 8, 20, 12, 3, 9, 9, 11]),
                "Confirmatory test of H3: the gap against window-Bayes at ρ = 0.6 and 0.8, largest model, horizon 1, "
                "step 30,000, five seeds; Bonferroni over eight combinations (PREREG section 7)", HYP,
                "A combination is positive at 95% if the lower end of its 95% interval is above the threshold, and "
                "positive after adjustment if the lower end of the 99.375% interval is. A printed −0.0000 is a "
                "negative value smaller than 0.00005 in size.")

    # architecture and training
    try:
        from rt.train import build_model
        params = {s: n_(sum(p.numel() for p in build_model(cfg, s).parameters())) for s in SIZES}
    except Exception:
        params = {s: "n/a" for s in SIZES}
    plan = {"xs": ("5", "laptop (mps)"), "s": ("5", "laptop (mps)"), "m": ("3", "RTX A6000 (cuda)"),
            "l": ("5", "RTX A6000 (cuda)")}
    rows = [[s, cfg["sizes"][s][0], cfg["sizes"][s][1], cfg["sizes"][s][2], params[s], plan[s][0], plan[s][1]]
            for s in SIZES]
    write_table("sizes", table(["size", "layers", "width", "heads", "parameters", "seeds run", "hardware"], rows),
                "Model sizes, parameter counts, and the seeds and hardware of the grid as run",
                "`configs/grid.json`, `rt/model.py`, `docs/DECISIONS.md` (deviation `prereg-v1.1`)")
    rows = [["optimiser", f"AdamW, learning rate {cfg['lr']}, betas ({cfg['betas'][0]}, {cfg['betas'][1]})"],
            ["weight decay", f"{cfg['weight_decay']}, applied to all parameters"],
            ["schedule", f"linear warm-up over {cfg['warmup_steps']} steps, then cosine to zero at step {n_(cfg['max_steps'])}"],
            ["steps", n_(cfg["max_steps"])],
            ["batch", f"{n_(cfg['batch_size'])} sequences, drawn afresh at every step"],
            ["loss", "squared error summed over the six horizons; full window: mean over all 80 positions; window W: one origin per sequence"],
            ["checkpoints", ", ".join(n_(c) for c in cfg["checkpoints"]) + " (as run; the frozen plan had six)"],
            ["seeds", ", ".join(str(s) for s in cfg["seeds"]) + " (size m and Family B: 0, 1, 2)"],
            ["horizons", f"1 to {cfg['horizons']}"],
            ["evaluation sets", f"{n_(cfg['eval_n_per_rho'])} sequences at each grid ρ; {n_(cfg['eval_n_prior'])} with ρ from the prior"]]
    write_table("training", table(["setting", "value"], rows, [12, 60]),
                "Training and evaluation settings", "`configs/grid.json`")

    # grade of evidence
    rows = [["H1, H2, H3", "simulated AR(1), Family A; size l; 5 seeds per cell; horizon 1; step 30,000",
             "confirmatory: pre-registered rows, margins and rules", "Sections [-@sec-h1] to [-@sec-h3]"],
            ["other sizes", "Family A; sizes xs and s (5 seeds), m (3 seeds)",
             "reported in the same tables; never enter a decision", "@sec-exploratory; Appendices [-@sec-app-verdicts], [-@sec-app-supplementary]"],
            ["training traces, horizons 2 to 6, error on revision", "Family A; checkpoints at 3,000, 10,000 and 30,000 steps",
             "exploratory", "@sec-exploratory"],
            ["human overlay", "Family B (unknown mean and scale); size l; windows full and 4; 3 seeds; published subject statistics",
             "descriptive; different data for people and networks", "@sec-overlay"],
            ["survey comparison", "SPF and real-time data; Family B networks",
             "illustrative; rules frozen at `prereg-v1.3`; not a test", "@sec-spf"]]
    write_table("grade", table(["stream", "data", "grade of evidence", "where"], rows, [14, 34, 26, 12]),
                "Scope and grade of evidence of each stream of results", "`docs/PREREG.md` sections 7 and 8")

    # exploratory: size
    rows = []
    for s in SIZES:
        row = [f"{s} ({cfg['sizes'][s][0]} / {cfg['sizes'][s][1]})", {"m": "3"}.get(s, "5")]
        for w in WINDOWS:
            c = counts(inp, s, w)
            extra = ", ".join(f"{c[k]} {lab}" for k, lab in (("different", "diff."), ("inconclusive", "inc.")) if c[k])
            row.append(f"{c['equivalent']}" + (f" ({extra})" if extra else ""))
        rows.append(row)
    write_table("size-counts", table(["size (layers / width)", "seeds", "W = 2", "W = 4", "W = 8", "W = 16", "full"], rows),
                "Exploratory: equivalent verdicts of 12 by model size and window, against the matching benchmark, horizon 1, "
                "step 30,000; other verdicts in brackets", SUM,
                "Only size l enters a decision. Size m uses three seeds, so its intervals use t with 2 degrees of freedom.")

    # exploratory: traces
    rows = []
    for st in STEPS:
        row = [n_(st)]
        for w in WINDOWS:
            c = counts(inp, "l", w, step=st)
            mx = max(inp.row("l", w, r, "excess_mse_pct", step=st).mean for r in RHOS)
            row.append(f"{c['equivalent']} ({sg(mx, 2)})")
        rows.append(row)
    write_table("traces", table(["step", "W = 2", "W = 4", "W = 8", "W = 16", "full"], rows),
                "Exploratory: equivalent verdicts of 12 by training step, size l, horizon 1, against the matching benchmark; "
                "in brackets, the largest mean excess error over the grid ρ, in percentage points", SUM)

    # exploratory: rho = 0
    rows = []
    for w in WINDOWS:
        r = inp.row("l", w, "0.0", "gap")
        rows.append([wlabel(w), BENCH_LABEL[bench_for(w)], us(r.bench_implied_persistence), us(r.implied_persistence),
                     sg(r.mean), ci(r.lo, r.hi), "yes" if r.lo > 0 or r.hi < 0 else "no", r.verdict])
    write_table("rho0", table(["window", "benchmark", "benchmark implied persistence", "model implied persistence",
                               "gap", "95% CI", "interval excludes zero", "verdict"], rows, [7, 12, 11, 11, 8, 19, 9, 10]),
                "Exploratory: the residual at ρ = 0, size l, horizon 1, step 30,000", SUM)

    # exploratory: horizons
    rows = []
    for h in range(1, 7):
        row = [str(h)]
        for w in WINDOWS:
            c = counts(inp, "l", w, hs=(h,))
            g = max(abs(inp.row("l", w, r, "gap", h=h).mean) for r in RHOS)
            m = max(abs(inp.row("l", w, r, "excess_mse_pct", h=h).mean) for r in RHOS)
            row.append(f"{c['equivalent']}; {us(g)}; {us(m, 3)}")
        rows.append(row)
    write_table("horizons", table(["horizon", "W = 2", "W = 4", "W = 8", "W = 16", "full"], rows),
                "Exploratory: horizons 1 to 6, size l, step 30,000, against the matching benchmark. Each cell gives the "
                "equivalent verdicts of 12; the largest absolute mean gap; the largest absolute mean excess error, in percentage points", SUM,
                "Horizon 1 is the confirmatory horizon and is repeated here for comparison.")

    # exploratory: error on revision
    E = eor_table(inp)
    rows = []
    for r in E[E.h == 1].itertuples():
        rows.append([r.window, r.rho, sg(r.bench_b), sg(r.model_b), sg(r.diff), us(r.sd), ci(r.lo, r.hi), str(r.n - 1)])
    write_table("eor", table(["W", "ρ", "benchmark b", "model b", "model − benchmark", "sd", "95% CI", "df"], rows),
                "Exploratory: error-on-revision coefficient b at horizon 1, size l, step 30,000, against the matching "
                "benchmark; the difference is computed seed by seed", "`results/metrics/`",
                "b is the slope of the forecast error on the forecast revision. The benchmark's own b is not zero for a "
                "finite window, because the revision compares forecasts made from two different windows. No margin was "
                "pre-registered for b, so no verdict is attached.")
    rows = []
    for r in E[E.h > 1].itertuples():
        rows.append([r.window, str(r.h), r.rho, sg(r.bench_b), sg(r.model_b), sg(r.diff), us(r.sd), ci(r.lo, r.hi), str(r.n - 1)])
    write_table("eor-horizons", table(["W", "h", "ρ", "benchmark b", "model b", "model − benchmark", "sd", "95% CI", "df"], rows),
                "Exploratory: error-on-revision coefficient b at horizons 2 to 5, size l, step 30,000, against the "
                "matching benchmark", "`results/metrics/`")
    K = kappa_table(inp)
    rows = [[r.window, r.rho, sg(r.mean), us(r.sd), ci(r.lo, r.hi), str(r.n - 1)] for r in K.itertuples()]
    write_table("kappa", table(["W", "ρ", "κ", "sd", "95% CI", "df"], rows),
                "Exploratory: κ, the slope of the model's deviation from full Bayes on the Bayes surprise, horizon 1, "
                "size l, step 30,000", "`results/metrics/`",
                "For a finite window κ measures the deviation from full Bayes, which includes the information limit; "
                "only the full-window rows compare the model with its matching benchmark.")

    # benchmarks alone
    B = pd.DataFrame(H["benchmarks"])
    bb = {(r.bench, r.window, r.rho): r.implied_persistence for r in B.itertuples()}
    rows = []
    for rho in RHO_KEYS:
        rows.append([rho, us(bb[("fire", "-", rho)]), us(bb[("ls", "-", rho)]), us(bb[("bayes", "-", rho)])]
                    + [us(bb[("window_bayes", w, rho)]) for w in H2_WINDOWS])
    write_table("benchmarks", table(["ρ", "full information", "least squares", "Bayes", "window-Bayes, W = 2",
                                     "W = 4", "W = 8", "W = 16"], rows),
                "Implied persistence of the benchmarks alone, Family A, horizon 1, on the evaluation sets", HYP,
                "No network enters this table. Implied persistence is the slope of the one-step forecast on the current value.")

    # overlay
    hum = {f"{h['rho']:.1f}": h for h in H["human"]}
    rows = []
    for rho in RHOS:
        h = hum[rho]
        f, w4 = inp.row("l", "full", rho, "gap", family="B"), inp.row("l", "4", rho, "gap", family="B")
        rows.append([rho, f"{us(h['implied_rho'], 3)} [{us(h['implied_rho'] - 1.96 * h['implied_rho_se'], 3)}, "
                          f"{us(h['implied_rho'] + 1.96 * h['implied_rho_se'], 3)}]",
                     us(f.bench_implied_persistence, 3), us(f.implied_persistence, 3),
                     us(w4.bench_implied_persistence, 3), us(w4.implied_persistence, 3)])
    write_table("overlay", table(["ρ", "people [95% CI]", "Bayes", "network, full window",
                                  "window-Bayes, W = 4", "network, W = 4"], rows),
                "Descriptive: implied persistence of the human subjects of Experiment 1 of Afrouzi et al. (2023), of the Family B benchmarks and of the Family B networks "
                "(size l, three seeds, step 30,000), horizon 1", f"{HYP}, {SUM}",
                "The human intervals are the point estimate plus or minus 1.96 participant-clustered standard errors. "
                "People forecast the experiment's series; the networks and benchmarks forecast simulated Family B series.")
    rows = []
    for w in ("full", "4"):
        for rho in RHO_KEYS:
            for col in COLS:
                r = inp.row("l", w, rho, col, family="B")
                rows.append([wlabel(w), rho, MEASURE[col], sg(r.mean), us(r.sd), ci(r.lo, r.hi), str(int(r.n_seeds) - 1),
                             r.verdict, ", ".join(sg(v) for v in r.values)])
    write_table("overlay-verdicts", table(["window", "ρ", "measure", "mean", "sd", "95% CI", "df", "verdict", "seed values"],
                                          rows, [6, 5, 9, 8, 7, 17, 3, 10, 24]),
                "Descriptive: Family B networks against their matching benchmark, size l, three seeds, horizon 1, step 30,000",
                SUM, "No hypothesis reads Family B. The verdict uses the same margins as Family A and t with 2 degrees of freedom.")

    # SPF
    spf = H["spf"]
    order = ["NGDP", "RGDP", "PGDP", "CPI", "UNEMP", "TB3M", "TN10Y"]
    cell = {(r["variable"], r["window"]): r for r in spf["rows"]}
    rows = []
    for v in order:
        def fmt(w):
            r = cell.get((v, w))
            if r is None:
                return "omitted"
            return f"{sg(r['b_model_mean'], 2)} [{', '.join(sg(x, 2) for x in r['b_model_values'])}]"
        any_r = cell.get((v, "4")) or cell.get((v, "full"))
        rows.append([v, sg(any_r["b_survey"], 2), fmt("full"), fmt("4"), str(any_r["T"])])
    write_table("spf", table(["variable", "survey b", "model b, full window: mean [seed values]",
                              "model b, W = 4: mean [seed values]", "quarters"], rows),
                "Illustrative: error-on-revision coefficient b of the SPF consensus forecast and of the Family B networks "
                "fed the same real-time histories; not a test", HYP,
                "Strict real-time sample; three seeds per cell. A positive b is underreaction, a negative b overreaction. "
                "One cell is omitted under the frozen per-cell rule.")

    # AKLMT design check
    dc = H["design_check"]
    rows = [[d["rho"], d["n_series"], us(d["series_mean"], 2), us(d["series_sd"], 2), us(d["series_min"], 0), us(d["series_max"], 0),
             us(d["innov_sd"], 2), us(d["abs_mean_over_sd"], 3), us(d["prior_sd_mu_over_sigma"], 1), f"{d['prior_p_var_ge']:.2e}"]
            for d in dc]
    write_table("aklmt-design", table(["ρ", "series", "series mean", "series sd", "min", "max", "innovation sd",
                                       "abs mean / innovation sd", "prior sd of μ / σ", "prior P(σ² ≥ observed)"], rows),
                "Descriptive: the design of Experiment 1 of Afrouzi et al. (2023) against the Family B prior", HYP,
                "The innovation standard deviation of the experiment's series is far outside the Family B prior for σ. "
                "This matters only for feeding raw human series to the networks, which the paper does not do.")

    # convergence
    rows = [[c["family"], c["size"], c["window"], c["n_runs"], c["expected_runs"], c["n_converged"],
             "yes" if c["converged"] else "no"] for c in H["convergence_cells"]]
    write_table("convergence-cells", table(["family", "size", "window", "runs", "runs planned", "runs meeting the plateau rule",
                                            "cell converged"], rows),
                "Descriptive: the plateau rule by cell (squared error at step 30,000 within 0.1% of step 10,000); it never "
                "changes a verdict", HYP)
    rows = [[r["cell_id"], ", ".join(n_(s) for s in r["steps"]), "yes" if r["converged"] else "no"] for r in H["runs"]]
    write_table("convergence-runs", table(["run", "checkpoints evaluated", "meets the plateau rule"], rows),
                "Descriptive: every run, the checkpoints evaluated and the plateau rule", HYP)

    # H2 other sizes, H3 other sizes
    rows = []
    for s in ("xs", "s", "m"):
        for w in H2_WINDOWS:
            for rho in RHOS:
                for col in COLS:
                    r = inp.row(s, w, rho, col)
                    rows.append([s, w, rho, MEASURE[col], sg(r.mean), us(r.sd), ci(r.lo, r.hi), str(int(r.n_seeds) - 1),
                                 r.verdict, ", ".join(sg(v) for v in r.values)])
    write_table("h2-other-sizes", table(["size", "W", "ρ", "measure", "mean", "sd", "95% CI", "df", "verdict", "seed values"],
                                        rows, [4, 3, 4, 9, 8, 7, 17, 3, 10, 34]),
                "The H2 rows at sizes xs, s and m (reported, never part of a decision): against window-Bayes, horizon 1, step 30,000",
                SUM)
    rows = []
    for s in ("xs", "s", "m"):
        for c in H["h3"]["other_sizes"][s]["combos"]:
            rows.append([s, c["window"], c["rho"], sg(c["mean"]), us(c["sd"]), ci(c["lo"], c["hi"]), sg(c["lo_adj"]),
                         str(c["n_seeds"] - 1), "yes" if c["positive_95"] else "no"])
    write_table("h3-other-sizes", table(["size", "W", "ρ", "mean gap", "sd", "95% CI", "adjusted lower end", "df", "positive at 95%"], rows),
                "The H3 rows at sizes xs, s and m (descriptive): gap against window-Bayes at ρ = 0.6 and 0.8, horizon 1, step 30,000",
                HYP)
    rows = []
    for w in WINDOWS:
        for rho in RHOS:
            for col in COLS:
                r = inp.row("xs", w, rho, col)
                if r.verdict != "equivalent":
                    rows.append([wlabel(w), rho, MEASURE[col], sg(r.mean), ci(r.lo, r.hi), r.verdict])
    write_table("xs-departures", table(["window", "ρ", "measure", "mean", "95% CI", "verdict"], rows),
                "Exploratory: every verdict of the smallest model (size xs) that is not equivalent, horizon 1, step 30,000, "
                "against the matching benchmark", SUM)

    # gate
    g = inp.gate["checks"]["benchmark"]["families"]
    rows = []
    for fam in ("A", "B"):
        for w in H2_WINDOWS:
            x = g[fam]["windows"][w]
            rows.append([fam, w, us(x["bayes"]), us(x["window_bayes"]), us(x["ls"]) if "ls" in x else "—"])
    write_table("gate", table(["family", "W", "Bayes", "window-Bayes", "windowed least squares"], rows),
                "The gate's benchmark check: squared error at horizon 1 (Family B standardised), 20,000 sequences",
                "`results/gate.json`",
                f"Bayes' own error-on-revision coefficient at horizon 1 on prior-drawn data: {sg(g['A']['eor_b_h1'], 5)} (Family A), "
                f"{sg(g['B']['eor_b_h1'], 5)} (Family B); tolerance ±0.01. Gate code hash `{inp.gate['code_hash']}`.")

    # coverage
    by = {}
    for cid in H["coverage"]["not_run_by_design"]:
        fam, size, w, s = cid.split("-")
        by.setdefault((fam, size, w), []).append(s[1:])
    rows = [[fam, size, w[1:], ", ".join(v), len(v)] for (fam, size, w), v in by.items()]
    write_table("not-run", table(["family", "size", "window", "seeds not run", "runs"], rows),
                "Cells of the configured grid not run by design under deviation `prereg-v1.1`", HYP)


# ---- figures ------------------------------------------------------------------------------

PALETTE = ("#000000", "#E69F00", "#56B4E9", "#009E73", "#0072B2", "#D55E00", "#CC79A7", "#F0E442")
WCOL = {"2": "#0072B2", "4": "#56B4E9", "8": "#009E73", "16": "#E69F00", "full": "#000000"}


def _style():
    """Okabe-Ito colours; TeX Gyre Pagella, the text face of the paper, when TeX Live has it."""
    import matplotlib as mpl
    mpl.use("Agg")
    from cycler import cycler
    from matplotlib import font_manager
    family = "DejaVu Serif"
    try:
        for style in ("regular", "bold", "italic", "bolditalic"):
            path = subprocess.run(["kpsewhich", f"texgyrepagella-{style}.otf"], capture_output=True,
                                  text=True).stdout.strip()
            if path:
                font_manager.fontManager.addfont(path)
                family = "TeX Gyre Pagella"
    except Exception:
        pass
    mpl.rcParams.update({
        "font.family": [family, "DejaVu Serif"], "font.size": 9, "axes.titlesize": 9, "axes.labelsize": 9,
        "legend.fontsize": 8, "xtick.labelsize": 8, "ytick.labelsize": 8, "mathtext.fontset": "custom",
        "mathtext.rm": family, "mathtext.it": family + ":italic", "mathtext.bf": family + ":bold",
        "axes.prop_cycle": cycler(color=list(PALETTE)), "axes.spines.top": False,
        "axes.spines.right": False, "axes.linewidth": 0.6, "lines.linewidth": 1.0,
        "xtick.major.width": 0.6, "ytick.major.width": 0.6, "axes.unicode_minus": True,
        "lines.markersize": 3.5, "legend.frameon": False, "savefig.dpi": 300, "pdf.fonttype": 42,
        "ps.fonttype": 42, "figure.dpi": 100, "savefig.bbox": "tight", "savefig.pad_inches": 0.03,
    })


def write_figure(fig, fid: str, caption: str, alt: str) -> None:
    import matplotlib.pyplot as plt
    stem = "fig_" + fid.replace("-", "_")
    fig.savefig(GEN / "figures" / f"{stem}.pdf", metadata={"CreationDate": None, "ModDate": None,
                                                           "Producer": None, "Creator": "analysis/paper_build.py"})
    plt.close(fig)
    (GEN / "figures" / f"{fid}.md").write_text(
        f"<!-- Generated by `{CMD}` from `docs/paper/figures.csv`. Do not edit. -->\n\n"
        f"![{caption}](_generated/figures/{stem}.pdf){{#fig-{fid} fig-alt=\"{alt}\"}}\n")
    FIGURES.append({"id": fid, "stem": stem, "caption": caption, "alt": alt})


def _err(ax, xs, rows, color, label=None, dx=0.0, marker="o", ls="-"):
    m = np.array([r.mean for r in rows])
    lo = np.array([r.lo for r in rows])
    hi = np.array([r.hi for r in rows])
    x = np.asarray(xs, dtype=float) + dx
    ax.errorbar(x, m, yerr=[m - lo, hi - m], color=color, marker=marker, ls=ls, lw=0.8, capsize=1.5,
                elinewidth=0.7, label=label)


def _margin(ax, m, zero=True):
    for y in (m, -m):
        ax.axhline(y, color="0.45", ls="--", lw=0.6)
    if zero:
        ax.axhline(0, color="0.75", lw=0.5)


def build_figures(inp: Inputs) -> None:
    _style()
    import matplotlib.pyplot as plt
    H = inp.H
    rhos = [float(r) for r in RHOS]

    # benchmarks alone
    B = pd.DataFrame(H["benchmarks"])
    bb = {(r.bench, r.window, r.rho): r.implied_persistence for r in B.itertuples()}
    fig, ax = plt.subplots(figsize=(4.6, 3.2))
    ax.plot(rhos, rhos, color="0.6", ls=":", label="truth (full information)")
    ax.plot(rhos, [bb[("bayes", "-", r)] for r in RHOS], color="#000000", marker="o", label="Bayes, full window")
    for w in ("16", "8", "4", "2"):
        ax.plot(rhos, [bb[("window_bayes", w, r)] for r in RHOS], color=WCOL[w], marker="s", label=f"window-Bayes, W = {w}")
    ax.set_xlabel("true persistence ρ")
    ax.set_ylabel("implied persistence, horizon 1")
    ax.set_xticks(rhos)
    ax.legend(loc="upper left")
    write_figure(fig, "benchmarks",
                 "Why a Bayesian looks biased: implied persistence of the exact benchmarks alone, Family A, horizon 1. "
                 "No network enters this figure.",
                 "Line chart of implied persistence against true persistence for the truth, full Bayes and window-Bayes at four windows.")

    # H1
    fig, axes = plt.subplots(1, 2, figsize=(7.0, 2.6))
    for ax, col, ylab in ((axes[0], "excess_mse_pct", "excess error against Bayes, pp"), (axes[1], "gap", "gap against Bayes")):
        _err(ax, rhos, [inp.row("l", "full", r, col) for r in RHOS], "#000000", ls="none")
        _margin(ax, MARGIN[col])
        ax.set_xlabel("true persistence ρ")
        ax.set_ylabel(ylab)
        ax.set_xticks(rhos)
        ax.set_ylim(-1.25 * MARGIN[col], 1.25 * MARGIN[col])
    write_figure(fig, "h1",
                 "H1: the largest model with the full window against Bayes, horizon 1, step 30,000; seed means with 95% "
                 "intervals, dashed lines at the pre-registered margins (±1 pp and ±0.02).",
                 "Two panels of seed means with intervals against true persistence, all close to zero and far inside dashed margin lines.")

    # H2 gap map (and excess map)
    for fid, col, ylab, cap in (
            ("h2-gap", "gap", "gap against the matching benchmark",
             "H2: gap against the matching benchmark (window-Bayes for W below full, Bayes for the full window), size l, "
             "horizon 1, step 30,000; seed means with 95% intervals, dashed lines at the ±0.02 margin."),
            ("h2-excess", "excess_mse_pct", "excess error against the matching benchmark, pp",
             "H2: excess squared error against the matching benchmark, size l, horizon 1, step 30,000; seed means with "
             "95% intervals, dashed lines at the ±1 pp margin.")):
        fig, axes = plt.subplots(1, 5, figsize=(7.0, 2.2), sharey=True)
        for ax, w in zip(axes, WINDOWS):
            _err(ax, rhos, [inp.row("l", w, r, col) for r in RHOS], WCOL[w], ls="none")
            _margin(ax, MARGIN[col])
            ax.set_title("full window" if w == "full" else f"W = {w}")
            ax.set_xticks([0, 0.4, 0.8])
            ax.set_xlabel("ρ")
            ax.set_ylim(-1.25 * MARGIN[col], 1.25 * MARGIN[col])
        axes[0].set_ylabel(ylab)
        write_figure(fig, fid, cap, "Five small panels, one per window, of seed means with intervals against true persistence, inside dashed margin lines.")

    # H3
    fig, ax = plt.subplots(figsize=(5.2, 2.8))
    t_adj = H["h3"]["bonferroni_t_n5"]
    for i, c in enumerate(H["h3"]["combos"]):
        half = t_adj * c["sd"] / math.sqrt(c["n_seeds"])
        ax.plot([i, i], [c["mean"] - half, c["mean"] + half], color="0.6", lw=0.7)
        ax.plot([i, i], [c["lo"], c["hi"]], color=WCOL[c["window"]], lw=2.0)
        ax.plot(i, c["mean"], "o", color=WCOL[c["window"]])
    ax.axhline(MARGIN["gap"], color="0.45", ls="--", lw=0.6)
    ax.axhline(0, color="0.75", lw=0.5)
    ax.text(7.45, MARGIN["gap"], "threshold +0.02", ha="right", va="bottom", fontsize=8, color="0.3")
    ax.set_xticks(range(8))
    ax.set_xticklabels([f"W = {c['window']}\nρ = {c['rho']}" for c in H["h3"]["combos"]])
    ax.set_ylabel("gap against window-Bayes")
    ax.set_ylim(-0.006, 0.024)
    write_figure(fig, "h3",
                 "H3: the gap against window-Bayes at the eight pre-registered window-ρ combinations, size l, horizon 1, "
                 "step 30,000. Thick bars are 95% intervals, thin bars the Bonferroni-adjusted 99.375% intervals; support "
                 "requires an adjusted lower end above the dashed threshold.",
                 "Eight seed means with nested intervals, all at or just below zero, far beneath a dashed threshold line at 0.02.")

    # size
    fig, axes = plt.subplots(1, 2, figsize=(7.0, 2.6), sharey=True)
    for ax, rho in zip(axes, ("0.6", "0.8")):
        for j, w in enumerate(WINDOWS):
            _err(ax, range(4), [inp.row(s, w, rho, "gap") for s in SIZES], WCOL[w],
                 label="full" if w == "full" else f"W = {w}", dx=(j - 2) * 0.08)
        _margin(ax, MARGIN["gap"])
        ax.set_xticks(range(4))
        ax.set_xticklabels(SIZES)
        ax.set_xlabel("model size")
        ax.set_title(f"ρ = {rho}")
    axes[0].set_ylabel("gap against the matching benchmark")
    axes[1].legend(loc="lower right", ncol=2)
    write_figure(fig, "size",
                 "Exploratory: gap against the matching benchmark by model size at ρ = 0.6 and 0.8, horizon 1, step 30,000; "
                 "seed means with 95% intervals, dashed lines at the ±0.02 margin.",
                 "Two panels of gaps by model size; only the smallest model leaves the margin, on the negative side.")

    # traces
    fig, axes = plt.subplots(1, 2, figsize=(7.0, 2.6), sharey=True)
    for ax, rho in zip(axes, ("0.6", "0.8")):
        for j, w in enumerate(WINDOWS):
            _err(ax, range(3), [inp.row("l", w, rho, "gap", step=st) for st in STEPS], WCOL[w],
                 label="full" if w == "full" else f"W = {w}", dx=(j - 2) * 0.06)
        _margin(ax, MARGIN["gap"])
        ax.set_xticks(range(3))
        ax.set_xticklabels([n_(s) for s in STEPS])
        ax.set_xlabel("training step")
        ax.set_title(f"ρ = {rho}")
    axes[0].set_ylabel("gap against the matching benchmark")
    axes[1].legend(loc="lower right", ncol=2)
    write_figure(fig, "traces",
                 "Exploratory: gap against the matching benchmark by training step at ρ = 0.6 and 0.8, size l, horizon 1; "
                 "seed means with 95% intervals, dashed lines at the ±0.02 margin.",
                 "Two panels of gaps at three checkpoints; intervals are wide at the early checkpoints and collapse onto zero at the last.")
    fig, axes = plt.subplots(1, 2, figsize=(7.0, 2.6))
    for ax, rho in zip(axes, ("0.0", "0.8")):
        for j, w in enumerate(WINDOWS):
            _err(ax, range(3), [inp.row("l", w, rho, "excess_mse_pct", step=st) for st in STEPS], WCOL[w],
                 label="full" if w == "full" else f"W = {w}", dx=(j - 2) * 0.06)
        _margin(ax, MARGIN["excess_mse_pct"])
        ax.set_xticks(range(3))
        ax.set_xticklabels([n_(s) for s in STEPS])
        ax.set_xlabel("training step")
        ax.set_title(f"ρ = {rho}")
        ax.set_ylabel("excess error, pp")
    axes[1].legend(loc="upper right", ncol=2)
    write_figure(fig, "traces-excess",
                 "Exploratory: excess squared error against the matching benchmark by training step at ρ = 0 and 0.8, size l, "
                 "horizon 1; seed means with 95% intervals, dashed lines at the ±1 pp margin.",
                 "Two panels of excess error at three checkpoints, falling from several points to inside the margin.")

    # rho = 0 residual by size
    fig, ax = plt.subplots(figsize=(4.6, 2.8))
    for j, w in enumerate(WINDOWS):
        _err(ax, range(4), [inp.row(s, w, "0.0", "gap") for s in SIZES], WCOL[w],
             label="full" if w == "full" else f"W = {w}", dx=(j - 2) * 0.08)
    _margin(ax, MARGIN["gap"])
    ax.set_xticks(range(4))
    ax.set_xticklabels(SIZES)
    ax.set_xlabel("model size")
    ax.set_ylabel("gap against the matching benchmark, ρ = 0")
    ax.legend(loc="upper right", ncol=2)
    write_figure(fig, "rho0",
                 "Exploratory: the residual at ρ = 0 by model size, horizon 1, step 30,000; seed means with 95% intervals, "
                 "dashed lines at the ±0.02 margin.",
                 "Gap at zero persistence by model size and window; large and positive for the smallest model, small and positive for the others.")

    # horizons
    fig, axes = plt.subplots(1, 2, figsize=(7.0, 2.6))
    for ax, col, ylab in ((axes[0], "gap", "largest |mean gap| over grid ρ"),
                          (axes[1], "excess_mse_pct", "largest |mean excess error| over grid ρ, pp")):
        for w in WINDOWS:
            ax.plot(range(1, 7), [max(abs(inp.row("l", w, r, col, h=h).mean) for r in RHOS) for h in range(1, 7)],
                    color=WCOL[w], marker="o", label="full" if w == "full" else f"W = {w}")
        ax.axhline(MARGIN[col], color="0.45", ls="--", lw=0.6)
        ax.set_xlabel("horizon")
        ax.set_ylabel(ylab)
        ax.set_ylim(0, 1.1 * MARGIN[col])
    axes[0].legend(loc="center right")
    write_figure(fig, "horizons",
                 "Exploratory: the largest absolute seed-mean gap and excess error over the grid ρ by horizon, size l, "
                 "step 30,000; the dashed line is the margin.",
                 "Two panels of maximum absolute deviations by horizon for each window, all well below the dashed margin line.")

    # error on revision
    E = eor_table(inp)
    e1 = E[(E.h == 1) & (E.rho != "prior")]
    fig, ax = plt.subplots(figsize=(3.6, 3.2))
    lim = [min(e1.bench_b.min(), e1.model_b.min()) - 0.05, max(e1.bench_b.max(), e1.model_b.max()) + 0.05]
    ax.plot(lim, lim, color="0.6", ls=":", lw=0.7)
    for w in WINDOWS:
        g = e1[e1.window == w]
        ax.plot(g.bench_b, g.model_b, "o", color=WCOL[w], label="full" if w == "full" else f"W = {w}", mfc="none")
    ax.set_xlabel("benchmark error-on-revision b")
    ax.set_ylabel("model error-on-revision b")
    ax.legend(loc="upper left")
    write_figure(fig, "eor",
                 "Exploratory: the model's error-on-revision coefficient against its matching benchmark's, horizon 1, size l, "
                 "step 30,000; one point per window and grid ρ, seed means; the dotted line is equality.",
                 "Scatter of model coefficient against benchmark coefficient lying on the diagonal.")

    # human overlay
    hum = sorted(H["human"], key=lambda h: h["rho"])
    fig, ax = plt.subplots(figsize=(4.8, 3.4))
    ax.plot(rhos, rhos, color="0.6", ls=":", label="truth")
    for w, color in (("full", "#000000"), ("4", "#56B4E9")):
        rows = [inp.row("l", w, r, "gap", family="B") for r in RHOS]
        ax.plot(rhos, [r.bench_implied_persistence for r in rows], color=color, lw=1.0,
                label="Bayes, full window" if w == "full" else "window-Bayes, W = 4")
        ax.plot(rhos, [r.implied_persistence for r in rows], "o", color=color, mfc="none", ms=5,
                label="network, full window" if w == "full" else "network, W = 4")
    hm = np.array([h["implied_rho"] for h in hum])
    hs = np.array([h["implied_rho_se"] for h in hum])
    ax.errorbar([h["rho"] for h in hum], hm, yerr=1.96 * hs, color="#D55E00", marker="D", ls="--", lw=0.8, capsize=2,
                label="people (Afrouzi et al. 2023, Exp. 1)")
    ax.set_xlabel("true persistence ρ")
    ax.set_ylabel("implied persistence, horizon 1")
    ax.set_xticks(rhos)
    ax.legend(loc="lower right")
    write_figure(fig, "overlay",
                 "Descriptive: implied persistence against true ρ. Family B networks (size l, three seeds, step 30,000) with the "
                 "full window and with W = 4, their Bayes and window-Bayes curves, and the human subjects of Experiment 1 of Afrouzi et al. (2023) "
                 "with 95% intervals; the dotted line is the truth.",
                 "Line chart with the network points lying on their benchmark curves and the human curve near the four-observation curve.")


