def header(sources: str) -> str:
    return f"<!-- Generated by `{CMD}` from {sources}. Do not edit. -->\n\n"


def app_preregistration(inp: Inputs) -> str:
    sec = inp.prereg_sections()
    entries = dict(inp.decision_entries())
    signoff = next(v for k, v in entries.items() if "owner sign-off" in k)
    sig = json.loads((inp.root / "docs" / "paper" / "signature.json").read_text())
    out = [header("`docs/PREREG.md`, `docs/DECISIONS.md`, `results/gate.json`, the git tags"),
           "```{=latex}\n\\begingroup\\footnotesize\\raggedright\\setstretch{1}\n```\n",
           "## Signature\n",
           "The pre-registration is `docs/PREREG.md` in the project repository. Its status line reads:\n",
           "> " + " ".join(l.strip() for l in sec["_preamble"].split("\n\n")[1].split("\n")) + "\n",
           "**The sign-off as recorded at the freeze.** The owner is the author. The sign-off is recorded in "
           "`docs/DECISIONS.md` under the heading \"2026-11-17: owner sign-off of the pre-registration\". The entry "
           "is the project log's record of the sign-off and holds no statement in the author's own words. "
           "It is reproduced verbatim:\n",
           "> " + "\n> ".join(escape_md(signoff.split("\n", 1)[1].strip()).split("\n")) + "\n",
           f"On {long_date(sig['date'])}, after every run had finished and H1 to H3 had been read, the author "
           f"confirmed that sign-off to the assistant in writing (\"{sig['statement']}\", {sig['date']}).\n",
           "This statement was not made at the freeze of 17 November 2026. It is a confirmation, three days later and "
           "with the results in view, of the sign-off recorded then, and it adds nothing to the evidence that the "
           "protocol preceded the runs; that evidence is the entry above, the tags and the run ledgers "
           "([Appendix @sec-app-replication]).\n",
           "The pre-registration was not lodged with an independent registry. It is a document in the author's "
           "repository, frozen by an annotated git tag; the tags existed only on the author's machine until the "
           "repository was made public (the last entry of [Appendix @sec-app-deviations]), so the tag dates are the author's "
           "record and not an independent timestamp.\n",
           "## Decision register (PREREG, \"Owner decisions\")\n",
           "Verbatim from `docs/PREREG.md`:\n",
           verbatim(sec["Owner decisions (2026-11-17)"].split("\n", 1)[1], 2) + "\n",
           "## Code binding\n",
           "The gate (`rt/gate.py`) certifies a hash of the code it ran: the SHA-256 of the sorted paths and contents of "
           "`rt/*.py` and `configs/*.json`. The sweep launcher refuses to start unless `results/gate.json` records a "
           "pass at the current hash, so any edit to the simulator, the benchmarks, the model, the training or "
           "evaluation code, or the grid re-opens the gate. Analysis code lives in `analysis/`, outside the hash "
           "(owner decision 6).\n",
           "- Gate code hash of every confirmatory run (`results/gate.json`, "
           f"`passed: {str(inp.gate['passed']).lower()}`; the same hash is recorded by the cloud instance's gate, "
           f"`results/cloud/gate.json`):\n\n    `{inp.gate['code_hash']}`\n",
           "- Hash history: `5b028b39…` (gate and learning check before the freeze), `ecb0d185…` (the gate re-run at "
           "the code tagged `prereg-v1`), `a2682c12…` (after deviation `prereg-v1.1` changed the checkpoint list in "
           "`configs/grid.json`; unchanged through `prereg-v1.4`).\n"]
    rows = [[f"`{t['name']}`", f"`{t['commit'][:12]}`", t["utc"], t["subject"]] for t in tags(inp)]
    out.append(table(["tag", "commit", "tagged (UTC)", "tag message"], rows, [8, 10, 12, 50]) + "\n")
    out.append("\nThe tags are annotated; the dates are the taggers' dates converted to UTC (git stores them in local "
               "time, UTC−5).\n")
    out.append("## The pre-registration, verbatim (sections 1 to 8, 10 and 11)\n")
    out.append("Section 9, everything seen before the freeze, is reproduced in [Appendix @sec-app-disclosures]. The text below "
               "is `docs/PREREG.md` at tag `prereg-v1`, unedited. It describes the grid as first planned (six "
               "checkpoints, 125 runs); the grid as run is deviation `prereg-v1.1` ([Appendix @sec-app-deviations]).\n")
    for name, body in sec.items():
        if name.startswith("_") or name.startswith("Owner decisions") or name.startswith("9."):
            continue
        out.append(verbatim(body, 1) + "\n")
    out.append("```{=latex}\n\\endgroup\n```\n")
    return "\n".join(out)


def app_deviations(inp: Inputs) -> str:
    entries = inp.decision_entries()
    conv_date = next(t.split(": ", 1)[0] for t, _ in entries if t.split(": ", 1)[1].startswith("Survey comparison conventions"))
    v13_utc = next((t["utc"] for t in tags(inp) if t["name"] == "prereg-v1.3"), "2026-11-18 01:19")
    out = [header("`docs/DECISIONS.md`, the git tags"),
           "## Summary of the decisions log\n",
           "One row per entry of `docs/DECISIONS.md`, in document order, with the entry's date (UTC), its kind, and "
           "whether confirmatory results had been seen when it was made. The last column uses the timing the log itself "
           "records, quoting it where it is stated; the entry \"timing of deviations v1.2 to v1.4\" fixes the timing of "
           "the three tags that followed the first confirmatory runs. Tag `prereg-v1.4` (the survey section wired into "
           "the report, off by default) has no entry of its own; its tag message and the timing entry place it before "
           "the analysis code had been run on any real metrics.\n",
           "A note on one date. The log says its dates are UTC, and it dates the entry \"Survey comparison conventions\" "
           f"{conv_date}. The tag that fixes those conventions, `prereg-v1.3`, was tagged {v13_utc} UTC, the following "
           "day in UTC and the same evening in local time (UTC−5), so that entry's date appears to be a local date. "
           "The commit and tag timestamps are authoritative, and the table classifies the entry's timing by the tag.\n",
           "```{=latex}\n\\begingroup\\scriptsize\\raggedright\\setstretch{1}\n```\n"]
    rows = []
    for i, (title, _) in enumerate(entries, 1):
        date, name = title.split(": ", 1)
        if name not in RESULTS_SEEN:
            raise KeyError(f"paper_build: no 'results seen' classification for DECISIONS entry {name!r}")
        kind, seen = RESULTS_SEEN[name]
        if name.startswith("Survey comparison conventions"):
            date += " (as logged; tag " + v13_utc + " UTC)"
        rows.append([str(i), date, name.replace("$", "\\$"), kind, seen])
    out.append(table(["no.", "date (UTC)", "entry", "kind", "confirmatory results seen"], rows, [3, 11, 30, 14, 40]) + "\n")
    out.append("```{=latex}\n\\endgroup\n```\n")
    out.append("## The decisions log, verbatim\n")
    out.append("`docs/DECISIONS.md`, unedited, one heading per entry. The log's own first line reads: \"Dates in this "
               "log are UTC; commit and tag timestamps in git are local time (UTC−5).\"\n")
    out.append("```{=latex}\n\\begingroup\\footnotesize\\raggedright\\setstretch{1}\n```\n")
    for _, body in entries:
        out.append(verbatim(body, 1) + "\n")
    out.append("```{=latex}\n\\endgroup\n```\n")
    return "\n".join(out)


def app_disclosures(inp: Inputs) -> str:
    sec = inp.prereg_sections()
    s9 = next(v for k, v in sec.items() if k.startswith("9."))
    return "\n".join([
        header("`docs/PREREG.md`"),
        "## Before the freeze (PREREG section 9, verbatim)\n",
        "```{=latex}\n\\begingroup\\footnotesize\\raggedright\\setstretch{1}\n```\n",
        verbatim(s9.split("\n", 1)[1], 2) + "\n",
        "```{=latex}\n\\endgroup\n```\n"])


def app_hypotheses(inp: Inputs) -> str:
    """PREREG section 7 as block quotes, one bold lead per hypothesis, for the methods section."""
    s7 = next(v for k, v in inp.prereg_sections().items() if k.startswith("7."))
    parts = re.split(r"(?m)^### ", s7.split("\n", 1)[1].strip())
    quote = lambda t: "\n".join("> " + ln if ln.strip() else ">" for ln in escape_md(t.strip()).split("\n"))  # noqa: E731
    out = [header("`docs/PREREG.md` (section 7)"), quote(parts[0]) + "\n"]
    for p in parts[1:]:
        title, body = p.split("\n", 1)
        out.append(f"**{title.strip()}** (PREREG section 7, verbatim)\n")
        out.append(quote(body) + "\n")
    return "\n".join(out)


def _verdict_rows(inp: Inputs, family, size, window, step, bench) -> list[list[str]]:
    rows = []
    for rho in RHO_KEYS:
        for h in range(1, 7):
            for col in COLS:
                r = inp.idx[(family, size, window, step, rho, h, bench, col)]
                rows.append([rho, str(h), MEASURE[col], str(int(r.n_seeds)), sg(r.mean), us(r.sd), sg(r.lo), sg(r.hi),
                             r.verdict, ", ".join(sg(v) for v in r.values)])
    return rows


def _diag_rows(inp: Inputs, family, size, window, step) -> list[list[str]]:
    rows = []
    for bench in ("bayes", "window_bayes"):
        for rho in RHO_KEYS:
            for h in range(1, 7):
                r = inp.idx[(family, size, window, step, rho, h, bench, "gap")]
                f = lambda v: "—" if v != v else sg(v)                      # noqa: E731
                rows.append([BENCH_LABEL[bench], rho, str(h), f(r.implied_persistence),
                             f(r.bench_implied_persistence), f(r.eor_b), f(r.bench_eor_b), f(r.kappa)])
    return rows


KEEP = "```{=latex}\n\\Needspace{8\\baselineskip}\n```\n"       # keep a lead line with its table


def app_verdicts(inp: Inputs) -> str:
    H = inp.H
    cells = [("A", s, w) for s in ("l", "m", "s", "xs") for w in WINDOWS] + [("B", "l", "full"), ("B", "l", "4")]
    conv = {(c["family"], c["size"], c["window"]): c for c in H["convergence_cells"]}
    index = []
    for fam, size, w in cells:
        cid = f"{fam}-{size}-w{w}"
        role = ("H1" if (fam, size, w) == ("A", "l", "full") else "H2, H3" if (fam, size) == ("A", "l")
                else "no decision" if fam == "A" else "descriptive")
        index.append([f"D.{len(index) + 1}", cid, fam, size, "full" if w == "full" else w,
                      str(int(inp.idx[(fam, size, w, 30000, "0.0", 1, "bayes", "gap")].n_seeds)), role,
                      f"`\\pageref{{sec-app-verdicts-{cid.lower()}}}`{{=latex}}"])
    out = [header("`results/summary.csv`, `results/hypotheses.json`"),
           "## Index of cells {.unnumbered .unlisted}\n",
           "The subsections of this appendix are not listed in the table of contents. Each page carries its cell in "
           "the running head.\n",
           "```{=latex}\n\\begingroup\\footnotesize\\raggedright\\setstretch{1}\n```\n",
           "| subsection | cell | family | size | window | seeds | read by | page |\n|---|---|---|---|---|--:|---|--:|\n"
           + "\n".join("| " + " | ".join(r) + " |" for r in index) + "\n",
           ": Index of Appendix D: one subsection per cell that was run, with the hypothesis that reads it and the "
           "page on which it starts. {#tbl-verdict-index}\n",
           "```{=latex}\n\\endgroup\n```\n",
           "```{=latex}\n\\begin{landscape}\\scriptsize\\raggedright\\setstretch{1}\\renewcommand{\\arraystretch}{0.92}\n```\n"]
    for fam, size, w in cells:
        n_seeds = int(inp.idx[(fam, size, w, 30000, "0.0", 1, "bayes", "gap")].n_seeds)
        c = conv[(fam, size, w)]
        wtxt = "full window" if w == "full" else f"window {w}"
        cid = f"{fam}-{size}-w{w}"
        role = ("H1 reads this cell (benchmark Bayes, horizon 1, step 30,000, grid ρ)." if (fam, size, w) == ("A", "l", "full")
                else "H2 and H3 read this cell (benchmark window-Bayes, horizon 1, step 30,000, grid ρ; H3 the gap at ρ = 0.6 and 0.8)."
                if fam == "A" and size == "l" else
                "No hypothesis reads this cell; its rows are reported and never enter a decision." if fam == "A" else
                "Family B is descriptive; no hypothesis reads this cell. Diagnostics are on standardised deviations.")
        out.append(f"## {cid}: Family {fam}, size {size}, {wtxt} {{#sec-app-verdicts-{cid.lower()}}}\n")
        out.append(f"<!-- {NOTE} -->\n")
        out.append(f"Seeds: {n_seeds}; 95% Student-t intervals with {n_seeds - 1} degrees of freedom. {role} "
                   f"Runs meeting the descriptive plateau rule: {c['n_converged']} of {c['n_runs']}. "
                   "Margins: ±1 pp of excess error, ±0.02 of gap. The verdict column applies the pre-registered rule to "
                   "every row; outside the rows a hypothesis names it is descriptive or exploratory. "
                   + ("For the full window the window-Bayes rows equal the Bayes rows. " if w == "full" else
                      "Rows against Bayes measure the deviation from the full-information-set forecaster, which includes the information limit. ")
                   + "A dash marks a diagnostic that is not defined for the row.\n")
        for step in STEPS:
            for bench in ("bayes", "window_bayes"):
                if w == "full" and bench == "window_bayes":
                    same = all(inp.idx[(fam, size, w, step, rho, h, "bayes", col)].values
                               == inp.idx[(fam, size, w, step, rho, h, "window_bayes", col)].values
                               for rho in RHO_KEYS for h in range(1, 7) for col in COLS)
                    assert same, "full-window window-Bayes rows must equal the Bayes rows"
                    out.append(f"**{cid}, step {n_(step)}, against window-Bayes:** identical, row for row and seed for "
                               "seed, to the table against Bayes above (checked by the generator), and not repeated.\n")
                    continue
                out.append(KEEP)
                out.append(f"**{cid}, step {n_(step)}, against {BENCH_LABEL[bench]}: verdicts with seed values.**\n")
                out.append(table(["ρ", "h", "measure", "n", "mean", "sd", "lo (95%)", "hi (95%)", "verdict", "seed values"],
                                 _verdict_rows(inp, fam, size, w, step, bench), [5, 2, 9, 2, 8, 7, 8, 8, 10, 40]) + "\n")
            out.append(KEEP)
            out.append(f"**{cid}, step {n_(step)}: diagnostic means over seeds.**\n")
            out.append(table(["benchmark", "ρ", "h", "model implied persistence", "benchmark implied persistence",
                              "model b", "benchmark b", "κ"], _diag_rows(inp, fam, size, w, step),
                             [10, 5, 2, 14, 14, 10, 10, 10]) + "\n")
    out.append("```{=latex}\n\\end{landscape}\n```\n")
    return "\n".join(out)


def upstream_sources(root: Path = ROOT) -> list[dict]:
    with open(root / "docs" / "paper" / "upstream_sources.csv", newline="") as f:
        return list(csv.DictReader(f))


def refresh_upstream() -> None:
    """Rewrite docs/paper/upstream_sources.csv from the companion repository's raw-data manifest."""
    man = json.loads((Path.home() / "Documents" / "expectations-without-hindsight" / "data" / "raw"
                      / "MANIFEST.json").read_text())["files"]
    want = ["aklmt/Replication.zip", "spf/2026-11-11/SPFmicrodata.xlsx", "rtdsm/2026-11-11/NOUTPUTQvQd.xlsx",
            "rtdsm/2026-11-11/ROUTPUTQvQd.xlsx", "rtdsm/2026-11-11/PQvQd.xlsx", "rtdsm/2026-11-11/cpiQvMd.xlsx",
            "rtdsm/2026-11-11/rucQvMd.xlsx", "fred/2026-11-11/TB3MS.csv", "fred/2026-11-11/GS10.csv"]
    used = {"aklmt/Replication.zip": "data/aklmt_figure2.csv"}
    with open(PAPER / "upstream_sources.csv", "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["file", "used_by", "source_url", "retrieved_utc", "bytes", "sha256"])
        for k in want:
            v = man[k]
            w.writerow([k, used.get(k, "data/spf_panel.parquet"), v["source_url"].split("?")[0], v["retrieved_at"],
                        v["bytes"], v["sha256"]])


def app_data(inp: Inputs, V: Vars) -> str:
    root = inp.root
    out = [header("`data/`, `data/PROVENANCE.md`, `docs/paper/upstream_sources.csv`, `results/ledger.csv`, "
                  "`results/cloud/ledger*.csv`, `docs/DECISIONS.md`, `uv.lock`, `pyproject.toml`, `README.md`")]
    out.append("## Raw-data manifest\n")
    out.append("Every confirmatory number in this paper comes from simulated data, generated by `rt/sim.py` from the "
               "seeds listed below; no external data enter H1 to H3. Two small derived files in `data/` feed the "
               "descriptive overlay and the illustrative survey comparison. They are in the repository, with their "
               "provenance in `data/PROVENANCE.md`.\n")
    prov = {"data/aklmt_figure2.csv": ("six rows of summary statistics (implied persistence and error-on-revision by ρ, with "
                                       "participant-clustered standard errors) derived from the replication package of Afrouzi, "
                                       "Kwon, Landier, Ma and Thesmar (2023), Experiment 1, by the companion repository "
                                       "`expectations-without-hindsight` at commit `57e9084`"),
            "data/spf_panel.parquet": ("1,351 rows (7 variables × 193 survey quarters, 1968Q4–2016Q4) written by "
                                       "`scripts/export_spf_panel.py` in the companion repository's environment (commit "
                                       "`b3b77cf`), raw-data snapshot 2026-11-11; regenerated 2026-11-18 under strict real time"),
            "data/PROVENANCE.md": "the provenance record itself"}
    rows = []
    for p in sorted((root / "data").iterdir()):
        rel = p.relative_to(root).as_posix()
        if p.is_file() and not p.name.startswith("."):
            rows.append([f"`{rel}`", prov.get(rel, ""), n_(p.stat().st_size), f"`{sha256(p)[:32]}` `{sha256(p)[32:]}`"])
    out.append("```{=latex}\n\\begingroup\\scriptsize\\raggedright\\setstretch{1}\n```\n")
    out.append("**Files in `data/`.**\n")
    out.append(table(["file", "what it is and where it comes from", "bytes", "SHA-256"], rows, [16, 40, 7, 28]) + "\n")
    out.append("**Upstream raw files behind them** (downloaded by the companion repository, not held in this one; the human "
               "curve is `data/aklmt_figure2.csv` and the survey panel `data/spf_panel.parquet`; from "
               "its raw-data manifest as recorded in `docs/paper/upstream_sources.csv`). The query string of a signed "
               "download link is dropped.\n")
    feeds = {"data/aklmt_figure2.csv": "human curve", "data/spf_panel.parquet": "survey panel"}
    rows = [[f"`{u['file'].split('/')[-1]}`", feeds[u["used_by"]], f"<{u['source_url']}>",
             u["retrieved_utc"].replace("T", " ").replace("Z", ""), n_(u["bytes"]), f"`{u['sha256'][:16]}`"]
            for u in upstream_sources(root)]
    out.append(table(["upstream file", "feeds", "source URL", "retrieved (UTC)", "bytes", "SHA-256 (first 16)"], rows,
                     [14, 9, 36, 13, 9, 19]) + "\n")
    out.append("The FRED series are `TB3MS` and `GS10` (the series identifier is a query parameter of the download "
               "link). The replication package of Afrouzi et al. (2023) is the Harvard Dataverse deposit "
               "`doi:10.7910/DVN/3Q6BHC`; only the six derived rows are redistributed here. Nothing in "
               "`data/spf_panel.parquet` comes from the replication packages of Bordalo et al. (2020) or Coibion and "
               "Gorodnichenko (2015) (`data/PROVENANCE.md`).\n")
    out.append("```{=latex}\n\\endgroup\n```\n")

    # ledgers
    L = ledgers(root)
    out.append("## Run ledgers\n")
    out.append(f"Each run appends one row to a ledger when it finishes: `results/ledger.csv` for the laptop and one "
               f"`results/cloud/ledger*.csv` per rented instance. The {len(L)} rows below are every row of every ledger, "
               f"in order of start time; all have return code 0. Seconds are wall-clock seconds of the run that finished, "
               "training and evaluation together; a resumed run records only its last segment, and runs shared the "
               "hardware, so the seconds do not sum to instance time.\n")
    out.append("```{=latex}\n\\begingroup\\scriptsize\\raggedright\\setstretch{1}\n```\n")
    Ls = L.sort_values(["start_iso", "cell_id"])
    names = sorted(L.ledger.unique(), key=lambda k: L[L.ledger == k].start_iso.min())
    label = {k: ("laptop" if k == "results/ledger.csv" else f"cloud {i}") for i, k in enumerate(names)}
    rows = [[r.cell_id, r.start_iso.replace("+00:00", "Z"), r.end_iso.replace("+00:00", "Z"), f"{r.seconds:,.1f}", r.device,
             str(r.returncode), label[r.ledger]] for r in Ls.itertuples()]
    out.append(table(["run", "start (UTC)", "end (UTC)", "seconds", "device", "return code", "ledger"], rows,
                     [12, 18, 18, 8, 6, 6, 8]) + "\n")
    g = L.groupby("ledger").agg(rows=("cell_id", "size"), hours=("seconds", lambda s: s.sum() / 3600),
                                first=("start_iso", "min"), last=("end_iso", "max"))
    rows = [[label[k], f"`{k}`", g.loc[k].rows, us(g.loc[k].hours, 1), g.loc[k]["first"].replace("+00:00", "Z"),
             g.loc[k]["last"].replace("+00:00", "Z")] for k in names]
    out.append(table(["ledger", "file", "rows", "run-hours", "first start (UTC)", "last end (UTC)"], rows,
                     [7, 34, 4, 7, 17, 17]) + "\n")
    out.append(": Ledger files: the label used in the listing above, the file, its rows, the sum of its run "
               "seconds in hours, and its first start and last end {#tbl-ledgers}\n")
    out.append("```{=latex}\n\\endgroup\n```\n")
    out.append("\nResumed runs, lost checkpoints and the one crashed attempt are recorded in `docs/DECISIONS.md` (entry "
               "\"timing of deviations v1.2 to v1.4, resumed runs\", [Appendix @sec-app-deviations]) and in the per-run logs under "
               "`results/logs/`, which are not in the public repository.\n")

    # cost
    g_ = V.get
    out.append("## Cost record\n")
    inst = g_("cost.instances_usd").split(", ")
    rows = [[f"sweep instance {i + 1}", f"about \\${c}"] for i, c in enumerate(inst)]
    rows += [["total, four sweep instances", f"about \\${g_('cost.total_usd')}"],
             [f"pilot instance (about {g_('cost.pilot_minutes')} minutes), if billed separately", f"about \\${g_('cost.pilot_usd')}"],
             ["total, range", f"\\${g_('cost.total_usd')} to about \\${g_('cost.total_with_pilot_usd')}"],
             ["instance-hours", f"about {g_('cost.hours')}"],
             ["price", f"\\${g_('cost.rate_usd')} per GPU-hour (RTX A6000)"],
             ["set aside for the sweep", f"\\${g_('cost.sweep_cap_usd')}"],
             ["pre-registered cloud cap (PREREG section 10)", f"\\${g_('cost.cloud_cap_usd')} of a \\${g_('cost.credit_usd')} credit"],
             ["owner's overall hard limit", f"\\${g_('cost.hard_limit_usd')}"],
             ["laptop runs", "no rented compute"]]
    out.append(table(["item", "amount"], rows) + "\n")
    out.append(": Cost record: estimated cloud spend by instance, the total as a range, and the budget limits it is "
               "read against (from `docs/DECISIONS.md`). {#tbl-cost}\n")
    out.append("\nThe spend is estimated from instance time at the listed price and has not yet been reconciled against the "
               "provider's bill, which the command line does not expose. The decisions log gives the total as "
               f"\"about \\${g_('cost.total_usd')} over four instances\" with the pilot included; the first instance's figure was "
               "read from the provider's console, and it is not known whether it includes the separate pilot instance "
               f"(about \\${g_('cost.pilot_usd')}). The total is therefore between \\${g_('cost.total_usd')} and about "
               f"\\${g_('cost.total_with_pilot_usd')}: over the \\${g_('cost.sweep_cap_usd')} set aside for the sweep, and at or "
               f"just over the \\${g_('cost.cloud_cap_usd')} pre-registered cloud cap depending on the pilot. The entry in "
               "[Appendix @sec-app-deviations] gives the cause of the overrun (a stalled file copy).\n")

    # environment
    out.append("## Environment\n")
    rows = [["Python", f"{g_('env.python')} (`pyproject.toml`); the lock file pins every package"],
            ["PyTorch", g_("env.torch")], ["NumPy", g_("env.numpy")], ["SciPy", g_("env.scipy")],
            ["pandas", g_("env.pandas")], ["Matplotlib", g_("env.matplotlib")], ["pyarrow", g_("env.pyarrow")],
            ["pytest", g_("env.pytest")],
            ["lock file", f"`uv.lock`, SHA-256 `{sha256(root / 'uv.lock')}`"],
            ["laptop", "Apple-silicon Mac (M2 Pro), PyTorch `mps` device; sizes xs and s, the gate, every benchmark cache and all analysis"],
            ["cloud", "one NVIDIA RTX A6000 (48 GB) per instance, Thunder Compute, 8 vCPUs, CUDA; sizes m and l and Family B; "
                      "TF32 matrix multiplies and one CPU thread per process, set by environment variables "
                      "(`TORCH_ALLOW_TF32_CUBLAS_OVERRIDE=1`, `OMP_NUM_THREADS=1`)"],
            ["paper", "Quarto with XeLaTeX; TeX Gyre Pagella"]]
    out.append(table(["component", "version or description"], rows, [10, 60]) + "\n")
    out.append(": Software and hardware {#tbl-environment}\n")
    out.append("\nTraining is seeded per step, so a run follows the same data stream on any machine; numbers agree to "
               "floating-point tolerance, not bit for bit. Laptop cells reproduce to 1e-6. Cloud cells used TF32, and "
               "re-evaluating two of them in full precision moved excess error by up to "
               f"{g_('tf32.max_mse_shift')} points and the gap by up to {g_('tf32.max_gap_shift')} (`docs/DECISIONS.md`).\n")

    # commands
    out.append("## Commands\n")
    out.append("The repository has no Makefile; every step is one command, run with `uv` from the repository root.\n")
    rows = [["`uv sync`", "create the locked environment"],
            ["`uv run pytest`", "the test suite"],
            ["`uv run python -m rt.gate`", "benchmark, planted-value and learning checks; writes `results/gate.json` with the code hash"],
            ["`uv run python -m rt.sweep`", "train and evaluate the grid (refuses without a green gate at the current hash); see `cloud/README.md` and `scripts/mac_sweep.sh`"],
            ["`uv run python -m rt.train`, `-m rt.evaluate`", "one run: train a cell; evaluate its checkpoints into `results/metrics/`"],
            ["`uv run python -m analysis.report`", "`RESULTS.md`, `results/summary.csv`, `results/hypotheses.json` and the report figures, from `results/metrics/`"],
            [f"`{CMD}`", "every generated file of this paper: variables, tables, figures and appendix sections"],
            ["`quarto render docs/paper`", "this PDF (and its `.tex` source)"],
            ["`uv run pytest -q tests/test_paper_build.py`", "checks that every variable resolves, that the decisions match `results/hypotheses.json` and that the generated tables reproduce `results/summary.csv`"]]
    out.append(table(["command", "what it does"], rows, [30, 50]) + "\n")
    out.append(": Commands {#tbl-commands}\n")
    out.append("\n`analysis.report` reads `results/metrics/`, which is in the repository, so every verdict can be "
               "recomputed without training anything. Model checkpoints (about 6 GB) and the benchmark cache (about "
               "9 GB) are not in the repository; the cache is rebuilt by `rt.evaluate`.\n")

    # seeds
    out.append("## Seed scheme\n")
    rows = [["training batch at step k of a run with seed s", "`SeedSequence([s, 0xA11CE, k])` (NumPy)",
             "depends only on the seed and the step: every cell of a family at a given seed sees the same paths (and, for "
             "windowed cells, the same origins); a resumed run follows the same stream"],
            ["parameter initialisation", "`torch.manual_seed(s)`", "s ∈ {0, 1, 2, 3, 4}"],
            ["evaluation set i of a family (i = 0..5 for ρ = 0, 0.2, …, 1; i = 6 for the prior set)",
             "`SeedSequence([10000 + i, tag])`, tag `0xE0A` (Family A) or `0xE0B` (Family B)",
             "a stream separate from every training stream; the same sets for every run"],
            ["survey drop-rule range", "seed `(30000, 0x5BF)`", "100,000 simulated Family B paths (`docs/DECISIONS.md`)"]]
    out.append("```{=latex}\n\\begingroup\\scriptsize\\raggedright\\setstretch{1}\n```\n")
    out.append(table(["what", "generator", "note"], rows, [22, 38, 30]) + "\n")
    out.append(": Seed scheme: how training batches, initial parameters and evaluation sets are seeded "
               "(`rt/train.py`, `rt/evaluate.py`) {#tbl-seeds}\n")
    out.append("```{=latex}\n\\endgroup\n```\n")
    return "\n".join(out)


# ---- driver -------------------------------------------------------------------------------

def write_csv(path: Path, header_: list[str], rows) -> None:
    with open(path, "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(header_)
        w.writerows(rows)


def build(root: Path = ROOT) -> Vars:
    TABLES.clear()
    FIGURES.clear()
    for sub in ("tables", "figures", "appendix"):
        (GEN / sub).mkdir(parents=True, exist_ok=True)
    inp = Inputs(root)
    V = build_variables(inp)
    (PAPER / "_variables.yml").write_text(json.dumps(V.tree, indent=2, sort_keys=True, ensure_ascii=False) + "\n")
    write_csv(PAPER / "variables_map.csv", ["key", "source", "locator", "fmt"], V.rows)
    build_tables(inp)
    build_figures(inp)
    write_csv(PAPER / "tables.csv", ["id", "source", "caption", "notes"],
              [[t["id"], t["source"], t["caption"], t["notes"]] for t in TABLES])
    write_csv(PAPER / "figures.csv", ["id", "stem", "caption", "alt"],
              [[f["id"], f["stem"], f["caption"], f["alt"]] for f in FIGURES])
    (GEN / "appendix" / "preregistration.md").write_text(app_preregistration(inp))
    (GEN / "appendix" / "deviations.md").write_text(app_deviations(inp))
    (GEN / "appendix" / "disclosures.md").write_text(app_disclosures(inp))
    (GEN / "appendix" / "verdicts.md").write_text(app_verdicts(inp))
    (GEN / "appendix" / "hypotheses.md").write_text(app_hypotheses(inp))
    (GEN / "appendix" / "data.md").write_text(app_data(inp, V))
    return V


def main(argv=None) -> int:
    import argparse
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("--refresh-upstream", action="store_true",
                    help="rewrite docs/paper/upstream_sources.csv from the companion repository's manifest")
    args = ap.parse_args(argv)
    if args.refresh_upstream:
        refresh_upstream()
    V = build()
    print(f"paper_build: {len(V.rows)} variables, {len(TABLES)} tables, {len(FIGURES)} figures -> {PAPER}")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
